"use client"

import * as React from "react"
import * as CheckboxPrimitive from "@radix-ui/react-checkbox"
import { Check } from "lucide-react"
import { cn } from "../utils/cn"
import { motion } from "framer-motion"

const Checkbox = React.forwardRef<
  React.ElementRef<typeof CheckboxPrimitive.Root>,
  React.ComponentPropsWithoutRef<typeof CheckboxPrimitive.Root>
>(({ className, ...props }, ref) => (
  <CheckboxPrimitive.Root
    ref={ref}
    className={cn(
      "peer h-5 w-5 shrink-0 rounded-md border border-muted-foreground/30 ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 transition-all duration-200 data-[state=checked]:bg-linear-to-br data-[state=checked]:from-primary data-[state=checked]:to-primary/80 data-[state=checked]:text-primary-foreground data-[state=checked]:border-transparent data-[state=checked]:shadow-lg data-[state=checked]:shadow-primary/20",
      className
    )}
    {...props}
  >
    <CheckboxPrimitive.Indicator
      className={cn("flex items-center justify-center text-current")}
    >
      <motion.div
        initial={{ scale: 0.5, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        transition={{ type: "spring", stiffness: 500, damping: 30 }}
      >
        <Check className="h-3.5 w-3.5 stroke-[3]" />
      </motion.div>
    </CheckboxPrimitive.Indicator>
  </CheckboxPrimitive.Root>
))
Checkbox.displayName = CheckboxPrimitive.Root.displayName

export { Checkbox }

command.content:
"use client"

import * as React from "react"
import * as DialogPrimitive from "@radix-ui/react-dialog"
import { motion, AnimatePresence } from "framer-motion"
import { Search } from "lucide-react"
import { cn } from "../utils/cn"

/**
 * Interface representing a Command palette item
 */
export interface CommandItem {
  label: string
  value: string
  icon?: React.ReactNode
  onSelect: () => void
}

/**
 * Props for the Command palette component
 */
export interface CommandProps {
  /**
   * Array of command items
   */
  items: CommandItem[]
  /**
   * Input search placeholder text
   * @default "Type a command or search..."
   */
  placeholder?: string
  /**
   * Whether the command dialog is open
   */
  open?: boolean
  /**
   * Callback fired when the open state changes
   */
  onOpenChange?: (open: boolean) => void
}

/**
 * Command component provides an interactive Command Palette (Cmd+K / Ctrl+K) dialog.
 */
const Command = React.forwardRef<HTMLDivElement, CommandProps>(
  ({ items, placeholder = "Type a command or search...", open: customOpen, onOpenChange }, ref) => {
    const [localOpen, setLocalOpen] = React.useState(false)
    const open = customOpen !== undefined ? customOpen : localOpen
    const setOpen = onOpenChange || setLocalOpen

    const [search, setSearch] = React.useState("")
    const [selectedIndex, setSelectedIndex] = React.useState(0)
    const listRef = React.useRef<HTMLDivElement>(null)

    // Toggle palette on Cmd+K / Ctrl+K
    React.useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
        if ((e.metaKey || e.ctrlKey) && e.key === "k") {
          e.preventDefault()
          setOpen(!open)
        }
      }
      window.addEventListener("keydown", handleKeyDown)
      return () => window.removeEventListener("keydown", handleKeyDown)
    }, [open, setOpen])

    // Filter items based on search query
    const filteredItems = React.useMemo(() => {
      if (!search.trim()) return items
      return items.filter((item) =>
        item.label.toLowerCase().includes(search.toLowerCase()) ||
        item.value.toLowerCase().includes(search.toLowerCase())
      )
    }, [items, search])

    // Reset selected item when filtered items change
    React.useEffect(() => {
      setSelectedIndex(0)
    }, [filteredItems])

    // Handle key navigation inside the list
    const handleKeyDown = (e: React.KeyboardEvent) => {
      if (filteredItems.length === 0) return

      if (e.key === "ArrowDown") {
        e.preventDefault()
        setSelectedIndex((prev) => (prev + 1) % filteredItems.length)
      } else if (e.key === "ArrowUp") {
        e.preventDefault()
        setSelectedIndex((prev) => (prev - 1 + filteredItems.length) % filteredItems.length)
      } else if (e.key === "Enter") {
        e.preventDefault()
        const selected = filteredItems[selectedIndex]
        if (selected) {
          selected.onSelect()
          setOpen(false)
        }
      }
    }

    return (
      <DialogPrimitive.Root open={open} onOpenChange={setOpen}>
        <AnimatePresence>
          {open && (
            <DialogPrimitive.Portal forceMount>
              {/* Overlay */}
              <DialogPrimitive.Overlay asChild>
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                  className="fixed inset-0 z-50 bg-black/60 backdrop-blur-md"
                />
              </DialogPrimitive.Overlay>

              {/* Palette Container */}
              <DialogPrimitive.Content asChild>
                <div className="fixed inset-0 z-50 flex items-start justify-center pt-[15vh] p-4">
                  <motion.div
                    initial={{ opacity: 0, scale: 0.95, y: -20 }}
                    animate={{ opacity: 1, scale: 1, y: 0 }}
                    exit={{ opacity: 0, scale: 0.95, y: -20 }}
                    transition={{ type: "spring", stiffness: 350, damping: 25 }}
                    onKeyDown={handleKeyDown}
                    ref={ref}
                    className="relative w-full max-w-[550px] bg-card/95 border border-border/80 rounded-2xl shadow-[0_20px_50px_rgba(0,0,0,0.5)] overflow-hidden flex flex-col focus:outline-none"
                  >
                    {/* Header Input */}
                    <div className="flex items-center gap-3 px-4 border-b border-border/40">
                      <Search className="h-4.5 w-4.5 text-muted-foreground/60 shrink-0" />
                      <input
                        autoFocus
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        placeholder={placeholder}
                        className="flex-1 h-12 bg-transparent text-[14px] outline-none placeholder:text-muted-foreground/40 font-medium"
                      />
                      <kbd className="inline-flex h-5.5 select-none items-center rounded border border-border bg-muted/40 px-1.5 font-mono text-[9px] font-medium text-muted-foreground/50">
                        ESC
                      </kbd>
                    </div>

                    {/* Scrollable list */}
                    <div
                      ref={listRef}
                      className="max-h-[300px] overflow-y-auto p-2 space-y-0.5"
                    >
                      {filteredItems.length > 0 ? (
                        filteredItems.map((item, idx) => {
                          const isSelected = idx === selectedIndex
                          return (
                            <button
                              key={item.value + idx}
                              onClick={() => {
                                item.onSelect()
                                setOpen(false)
                              }}
                              onMouseEnter={() => setSelectedIndex(idx)}
                              className={cn(
                                "w-full flex items-center gap-3 px-3 py-2 rounded-xl text-sm transition-all text-left outline-none",
                                isSelected
                                  ? "bg-primary/10 text-primary font-medium shadow-[inset_0_0_1px_rgba(var(--primary-rgb),0.2)]"
                                  : "text-foreground hover:bg-muted/40"
                              )}
                            >
                              {item.icon && (
                                <span className={cn("shrink-0", isSelected ? "text-primary" : "text-muted-foreground/70")}>
                                  {item.icon}
                                </span>
                              )}
                              <span className="flex-1 truncate">{item.label}</span>
                              {isSelected && (
                                <span className="text-[10px] uppercase font-bold tracking-widest text-primary/80 bg-primary/10 px-1.5 py-0.5 rounded-md">
                                  Select
                                </span>
                              )}
                            </button>
                          )
                        })
                      ) : (
                        <div className="py-8 text-center text-sm text-muted-foreground/60">
                          No results found.
                        </div>
                      )}
                    </div>

                    {/* Footer guides */}
                    <div className="flex items-center gap-4 px-4 py-2.5 border-t border-border/40 bg-muted/10">
                      <div className="flex items-center gap-1 text-[10px] text-muted-foreground/50">
                        <kbd className="inline-flex h-4 items-center rounded border border-border bg-muted/20 px-1 font-mono text-[8px]">↑↓</kbd>
                        <span>Navigate</span>
                      </div>
                      <div className="flex items-center gap-1 text-[10px] text-muted-foreground/50">
                        <kbd className="inline-flex h-4 items-center rounded border border-border bg-muted/20 px-1 font-mono text-[8px]">↵</kbd>
                        <span>Select</span>
                      </div>
                    </div>
                  </motion.div>
                </div>
              </DialogPrimitive.Content>
            </DialogPrimitive.Portal>
          )}
        </AnimatePresence>
      </DialogPrimitive.Root>
    )
  }
)

Command.displayName = "Command"

export { Command }

dark-mode.content:
"use client";

import { useState } from "react";
import { motion } from "framer-motion";
import { Sun, Moon, Monitor } from "lucide-react";
import { cn } from "../utils/cn";

export interface DarkModeToggleProps {
  theme?: "light" | "dark" | "system";
  variant?: "pill" | "icon" | "segmented";
  size?: "sm" | "md" | "lg";
  showLabel?: boolean;
  onChange?: (theme: "light" | "dark" | "system") => void;
  className?: string;
}

export function DarkModeToggle({
  theme: controlledTheme,
  variant = "pill",
  size = "md",
  showLabel = false,
  onChange,
  className,
}: DarkModeToggleProps) {
  const [internalTheme, setInternalTheme] = useState<"light" | "dark" | "system">("dark");

  const activeTheme = controlledTheme !== undefined ? controlledTheme : internalTheme;

  const handleToggle = (newTheme: "light" | "dark" | "system") => {
    if (controlledTheme === undefined) {
      setInternalTheme(newTheme);
      // Toggle class on documentElement for vanilla / non-provider environments
      if (typeof document !== "undefined") {
        if (newTheme === "dark") {
          document.documentElement.classList.add("dark");
        } else if (newTheme === "light") {
          document.documentElement.classList.remove("dark");
        }
      }
    }
    onChange?.(newTheme);
  };

  const isDark = activeTheme === "dark";

  if (variant === "icon") {
    return (
      <button
        type="button"
        onClick={() => handleToggle(isDark ? "light" : "dark")}
        className={cn(
          "relative flex items-center justify-center rounded-xl border border-border/80 bg-card hover:bg-muted/60 text-foreground transition-all duration-200 cursor-pointer shadow-xs",
          size === "sm" ? "w-8 h-8" : size === "lg" ? "w-11 h-11" : "w-9 h-9",
          className
        )}
        title={\`Switch to \${isDark ? "light" : "dark"} theme\`}
        aria-label="Toggle theme"
      >
        <motion.div
          key={isDark ? "dark" : "light"}
          initial={{ rotate: -90, scale: 0.8, opacity: 0 }}
          animate={{ rotate: 0, scale: 1, opacity: 1 }}
          exit={{ rotate: 90, scale: 0.8, opacity: 0 }}
          transition={{ duration: 0.2 }}
        >
          {isDark ? (
            <Moon className={size === "sm" ? "w-3.5 h-3.5 text-primary" : "w-4.5 h-4.5 text-primary"} />
          ) : (
            <Sun className={size === "sm" ? "w-3.5 h-3.5 text-amber-500" : "w-4.5 h-4.5 text-amber-500"} />
          )}
        </motion.div>
      </button>
    );
  }

  if (variant === "segmented") {
    return (
      <div
        className={cn(
          "inline-flex items-center gap-1 p-1 rounded-xl border border-border/80 bg-muted/40 backdrop-blur-md shadow-xs",
          className
        )}
      >
        {(["light", "dark", "system"] as const).map((t) => {
          const isActive = activeTheme === t;
          return (
            <button
              key={t}
              type="button"
              onClick={() => handleToggle(t)}
              className={cn(
                "inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium capitalize transition-all duration-200 cursor-pointer",
                isActive
                  ? "bg-card text-foreground shadow-xs border border-border/60 font-semibold"
                  : "text-muted-foreground hover:text-foreground"
              )}
            >
              {t === "light" && <Sun className="w-3.5 h-3.5 text-amber-500" />}
              {t === "dark" && <Moon className="w-3.5 h-3.5 text-primary" />}
              {t === "system" && <Monitor className="w-3.5 h-3.5 text-muted-foreground" />}
              {showLabel && <span>{t}</span>}
            </button>
          );
        })}
      </div>
    );
  }

  // Default: Pill toggle
  const dimensions =
    size === "sm"
      ? { track: "w-11 h-6", thumb: "w-4.5 h-4.5", icon: "w-2.5 h-2.5" }
      : size === "lg"
      ? { track: "w-16 h-9", thumb: "w-7 h-7", icon: "w-4 h-4" }
      : { track: "w-14 h-7.5", thumb: "w-5.5 h-5.5", icon: "w-3 h-3" };

  return (
    <div className={cn("inline-flex items-center gap-3", className)}>
      <button
        type="button"
        onClick={() => handleToggle(isDark ? "light" : "dark")}
        className={cn(
          "relative rounded-full transition-colors duration-300 border border-border/80 shadow-xs cursor-pointer p-0.75",
          isDark ? "bg-zinc-900 border-primary/40" : "bg-zinc-200 dark:bg-zinc-800",
          dimensions.track
        )}
        title={\`Switch to \${isDark ? "light" : "dark"} mode\`}
        aria-label="Toggle dark mode"
      >
        <motion.div
          animate={{
            x: isDark ? (size === "sm" ? 20 : size === "lg" ? 28 : 25) : 0,
          }}
          transition={{ type: "spring", stiffness: 500, damping: 30 }}
          className={cn(
            "rounded-full bg-white shadow-md flex items-center justify-center transition-colors",
            dimensions.thumb
          )}
        >
          {isDark ? (
            <Moon className={cn(dimensions.icon, "text-zinc-900")} />
          ) : (
            <Sun className={cn(dimensions.icon, "text-amber-500")} />
          )}
        </motion.div>
      </button>

      {showLabel && (
        <span className="text-xs font-semibold text-foreground/90 capitalize select-none">
          {activeTheme} mode
        </span>
      )}
    </div>
  );
}

data-display.content:
"use client"

import * as React from "react"
import { Check, Copy, type LucideIcon } from "lucide-react"
import { cn } from "../utils/cn"
import { Button } from "./button"
import { Avatar, AvatarFallback, AvatarImage } from "./avatar"

// 1. Kbd - Keyboard shortcut component
export function Kbd({ className, children, ...props }: React.HTMLAttributes<HTMLElement>) {
  return (
    <kbd
      className={cn(
        "pointer-events-none inline-flex h-5 select-none items-center gap-1 rounded border border-border bg-muted px-1.5 font-mono text-[10px] font-medium text-muted-foreground opacity-100",
        className
      )}
      {...props}
    >
      {children}
    </kbd>
  )
}

// 2. AvatarGroup - Overlapping avatars
interface AvatarGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Описание для limit
   * @default undefined
   */
  limit?: number
  /**
   * Описание для items
   * @default undefined
   */
  items: { src?: string; fallback: string }[]
}

export function AvatarGroup({ items, limit = 3, className, ...props }: AvatarGroupProps) {
  const visibleItems = items.slice(0, limit)
  const remaining = items.length - limit

  return (
    <div className={cn("flex -space-x-3 items-center", className)} {...props}>
      {visibleItems.map((item, index) => (
        <Avatar key={index} className="border-2 border-background w-8 h-8">
          {item.src && <AvatarImage src={item.src} />}
          <AvatarFallback>{item.fallback}</AvatarFallback>
        </Avatar>
      ))}
      {remaining > 0 && (
        <div className="flex items-center justify-center w-8 h-8 rounded-full bg-muted border-2 border-background text-xs font-medium">
          +{remaining}
        </div>
      )}
    </div>
  )
}

// 3. StatCard - Individual stat card
interface StatCardProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Описание для title
   * @default undefined
   */
  title: string
  /**
   * Описание для value
   * @default undefined
   */
  value: string
  /**
   * Описание для description
   * @default undefined
   */
  description?: string
  /**
   * Описание для icon
   * @default undefined
   */
  icon?: LucideIcon
  /**
   * Описание для trend
   * @default undefined
   */
  trend?: {
    /**
     * Описание для value
     * @default undefined
     */
    value: string
    /**
     * Описание для positive
     * @default undefined
     */
    positive: boolean
  }
}

export function StatCard({ title, value, description, icon: Icon, trend, className, ...props }: StatCardProps) {
  return (
    <div
      className={cn(
        "rounded-xl border border-border bg-card p-6 shadow-sm hover:shadow-md transition-shadow",
        className
      )}
      {...props}
    >
      <div className="flex justify-between items-start">
        <div className="space-y-2">
          <p className="text-sm font-medium text-muted-foreground">{title}</p>
          <div className="flex items-baseline space-x-2">
            <h2 className="text-3xl font-bold tracking-tight">{value}</h2>
            {trend && (
              <span
                className={cn(
                  "text-xs font-medium px-1.5 py-0.5 rounded-full",
                  trend.positive ? "bg-green-500/10 text-green-500" : "bg-red-500/10 text-red-500"
                )}
              >
                {trend.positive ? "+" : "-"}{trend.value}
              </span>
            )}
          </div>
          {description && <p className="text-xs text-muted-foreground">{description}</p>}
        </div>
        {Icon && (
          <div className="p-2 bg-muted rounded-md">
            <Icon className="h-5 w-5 text-muted-foreground" />
          </div>
        )}
      </div>
    </div>
  )
}

// 4. Timeline - Vertical timeline
interface TimelineItem {
  title: string
  description: string
  time: string
  status?: "completed" | "current" | "upcoming"
}

export function Timeline({ items, className }: { items: TimelineItem[]; className?: string }) {
  return (
    <div className={cn("space-y-8", className)}>
      {items.map((item, index) => (
        <div key={index} className="relative flex gap-6 pb-8 last:pb-0">
          {index !== items.length - 1 && (
            <div className="absolute left-[11px] top-4 h-full w-0.5 bg-border" />
          )}
          <div
            className={cn(
              "relative z-10 flex h-6 w-6 shrink-0 items-center justify-center rounded-full border-2",
              item.status === "completed" && "border-primary bg-primary text-primary-foreground",
              item.status === "current" && "border-primary bg-background",
              item.status === "upcoming" && "border-border bg-muted"
            )}
          >
            {item.status === "completed" && <Check className="h-3 w-3" />}
            {item.status === "current" && <div className="h-2 w-2 rounded-full bg-primary" />}
          </div>
          <div className="space-y-1.5">
            <div className="flex items-center gap-2">
              <h4 className="font-semibold">{item.title}</h4>
              <span className="text-xs text-muted-foreground">{item.time}</span>
            </div>
            <p className="text-sm text-muted-foreground">{item.description}</p>
          </div>
        </div>
      ))}
    </div>
  )
}

// 5. CodeBlock - Code block with copy button
interface CodeBlockProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Описание для code
   * @default undefined
   */
  code: string
  /**
   * Описание для language
   * @default undefined
   */
  language?: string
}

export function CodeBlock({ code, language, className, ...props }: CodeBlockProps) {
  const [copied, setCopied] = React.useState(false)

  const handleCopy = () => {
    navigator.clipboard.writeText(code)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  return (
    <div className={cn("relative rounded-lg border bg-muted/50 p-4 font-mono text-sm overflow-hidden", className)} {...props}>
      <div className="absolute right-4 top-4">
        <Button variant="ghost" size="icon" className="h-8 w-8" onClick={handleCopy}>
          {copied ? <Check className="h-4 w-4" /> : <Copy className="h-4 w-4" />}
        </Button>
      </div>
      {language && (
        <div className="absolute left-4 top-2 text-xs text-muted-foreground uppercase">
          {language}
        </div>
      )}
      <pre className={cn("overflow-x-auto", language && "pt-6")}>
        <code>{code}</code>
      </pre>
    </div>
  )
}

// 6. PricingCard - Premium pricing card
interface PricingCardProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Описание для title
   * @default undefined
   */
  title: string
  /**
   * Описание для price
   * @default undefined
   */
  price: string
  /**
   * Описание для description
   * @default undefined
   */
  description: string
  /**
   * Описание для features
   * @default undefined
   */
  features: string[]
  /**
   * Описание для buttonText
   * @default undefined
   */
  buttonText?: string
  /**
   * Описание для popular
   * @default undefined
   */
  popular?: boolean
}

export function PricingCard({ title, price, description, features, buttonText = "Get Started", popular = false, className, ...props }: PricingCardProps) {
  return (
    <div
      className={cn(
        "rounded-2xl border bg-card p-6 flex flex-col justify-between relative",
        popular && "border-primary shadow-lg shadow-primary/5",
        className
      )}
      {...props}
    >
      {popular && (
        <div className="absolute -top-3 left-1/2 -translate-x-1/2 bg-primary text-primary-foreground text-xs font-semibold px-3 py-1 rounded-full">
          Most Popular
        </div>
      )}
      <div>
        <div className="space-y-1.5 mb-6">
          <h3 className="text-xl font-bold">{title}</h3>
          <p className="text-sm text-muted-foreground">{description}</p>
        </div>
        <div className="mb-6">
          <span className="text-4xl font-bold">{price}</span>
          <span className="text-muted-foreground">/mo</span>
        </div>
        <ul className="space-y-3 mb-6 text-sm">
          {features.map((feature, index) => (
            <li key={index} className="flex items-center gap-2">
              <Check className="h-4 w-4 text-primary" />
              <span>{feature}</span>
            </li>
          ))}
        </ul>
      </div>
      <Button variant={popular ? "default" : "outline"} className="w-full">
        {buttonText}
      </Button>
    </div>
  )
}

// 7. Divider - Simple divider line
export interface DividerProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * The orientation of the divider
   * @default "horizontal"
   */
  /**
   * Описание для orientation
   * @default undefined
   */
  orientation?: "horizontal" | "vertical";
}

export function Divider({ orientation = "horizontal", className, ...props }: DividerProps) {
  return (
    <div
      className={cn(
        "bg-border shrink-0",
        orientation === "horizontal" ? "h-px w-full" : "w-px h-full",
        className
      )}
      {...props}
    />
  );
}

dialog.content:
"use client"

import * as React from "react"
import * as DialogPrimitive from "@radix-ui/react-dialog"
import { X } from "lucide-react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "../utils/cn"

const Dialog = DialogPrimitive.Root

const DialogTrigger = DialogPrimitive.Trigger

const DialogPortal = DialogPrimitive.Portal

const DialogClose = DialogPrimitive.Close

const DialogOverlay = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Overlay>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Overlay
    ref={ref}
    className={cn(
      "fixed inset-0 z-50 bg-black/50 backdrop-blur-sm data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0",
      className
    )}
    {...props}
  />
))
DialogOverlay.displayName = DialogPrimitive.Overlay.displayName

const dialogContentVariants = cva(
  "fixed left-[50%] top-[50%] z-50 grid w-full translate-x-[-50%] translate-y-[-50%] gap-4 border bg-background/95 backdrop-blur-md p-6 shadow-2xl duration-200 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:scale-95 data-[state=open]:scale-100 data-[state=closed]:translate-y-[-48%] data-[state=open]:translate-y-[-50%] rounded-2xl",
  {
    variants: {
      variant: {
        default: "border-border/50",
        glass: "bg-white/10 backdrop-blur-xl border-white/20 shadow-2xl",
        destructive: "border-destructive/20",
        success: "border-green-500/20",
        fullscreen: "max-w-full h-screen rounded-none",
        drawer: "sm:max-w-full sm:h-[50vh] sm:rounded-b-none sm:rounded-t-[20px] fixed bottom-0 top-auto translate-y-0 data-[state=closed]:slide-out-to-bottom data-[state=open]:slide-in-from-bottom",
      },
      size: {
        sm: "max-w-sm",
        md: "max-w-md",
        lg: "max-w-lg",
        xl: "max-w-xl",
        "2xl": "max-w-2xl",
        full: "max-w-[95vw] md:max-w-[90vw]",
      },
      scrollable: {
        true: "max-h-[80vh] overflow-y-auto",
        false: "",
      }
    },
    defaultVariants: {
      variant: "default",
      size: "lg",
      scrollable: false,
    },
  }
)

export interface DialogContentProps
  extends React.ComponentPropsWithoutRef<typeof DialogPrimitive.Content>,
    VariantProps<typeof dialogContentVariants> {}

const DialogContent = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Content>,
  DialogContentProps
>(({ className, variant, size, scrollable, children, ...props }, ref) => (
  <DialogPortal>
    <DialogOverlay />
    <DialogPrimitive.Content
      ref={ref}
      className={cn(dialogContentVariants({ variant, size, scrollable, className }))}
      {...props}
    >
      {children}
      <DialogPrimitive.Close className="absolute right-4 top-4 rounded-full p-1 opacity-70 ring-offset-background transition-opacity hover:opacity-100 hover:bg-muted focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:pointer-events-none">
        <X className="h-4 w-4" />
        <span className="sr-only">Close</span>
      </DialogPrimitive.Close>
    </DialogPrimitive.Content>
  </DialogPortal>
))
DialogContent.displayName = DialogPrimitive.Content.displayName

const DialogHeader = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    className={cn(
      "flex flex-col space-y-1.5 text-center sm:text-left",
      className
    )}
    {...props}
  />
)
DialogHeader.displayName = "DialogHeader"

const DialogFooter = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    className={cn(
      "flex flex-col-reverse sm:flex-row sm:justify-end sm:space-x-2",
      className
    )}
    {...props}
  />
)
DialogFooter.displayName = "DialogFooter"

const DialogTitle = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Title>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Title>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Title
    ref={ref}
    className={cn(
      "text-xl font-semibold leading-none tracking-tight bg-linear-to-br from-foreground to-foreground/70 bg-clip-text text-transparent",
      className
    )}
    {...props}
  />
))
DialogTitle.displayName = DialogPrimitive.Title.displayName

const DialogDescription = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Description>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Description>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Description
    ref={ref}
    className={cn("text-sm text-muted-foreground leading-relaxed", className)}
    {...props}
  />
))
DialogDescription.displayName = DialogPrimitive.Description.displayName

export {
  Dialog,
  DialogPortal,
  DialogOverlay,
  DialogClose,
  DialogTrigger,
  DialogContent,
  DialogHeader,
  DialogFooter,
  DialogTitle,
  DialogDescription,
}

dock.content:
"use client"

import React, { useRef } from "react"
import { motion, useMotionValue, useSpring, useTransform } from "framer-motion"
import { cn } from "../utils/cn"

export interface DockProps {
  /**
   * Описание для items
   * @default undefined
   */
  items: {
    /**
     * Описание для icon
     * @default undefined
     */
    icon: React.ReactNode
    /**
     * Описание для label
     * @default undefined
     */
    label: string
    /**
     * Описание для onClick
     * @default undefined
     */
    onClick?: () => void
  }[]
  /**
   * Описание для className
   * @default undefined
   */
  className?: string
  /**
   * Описание для magnification
   * @default undefined
   */
  magnification?: number
  /**
   * Описание для distance
   * @default undefined
   */
  distance?: number
}

export function Dock({
  items,
  className,
  magnification = 60,
  distance = 140,
}: DockProps) {
  const mouseX = useMotionValue(Infinity);
  const numMagnification = Number(magnification) || 60;
  const numDistance = Number(distance) || 140;

  return (
    <motion.div
      onMouseMove={(e) => mouseX.set(e.clientX)}
      onMouseLeave={() => mouseX.set(Infinity)}
      className={cn(
        "mx-auto flex h-14 items-end gap-3 rounded-2xl border border-border bg-background/80 px-4 pb-2 backdrop-blur-md",
        className
      )}
    >
      {items.map((item, i) => (
        <DockIcon key={i} mouseX={mouseX} magnification={numMagnification} distance={numDistance} {...item} />
      ))}
    </motion.div>
  )
}

function DockIcon({
  mouseX,
  magnification,
  distance,
  icon,
  label,
  onClick,
}: {
  mouseX: any
  magnification: number
  distance: number
  icon: React.ReactNode
  label: string
  onClick?: () => void
}) {
  const ref = useRef<HTMLDivElement>(null)

  const numDistance = Number(distance) || 140
  const numMagnification = Number(magnification) || 60

  const distanceVal = useTransform(mouseX, (val: number) => {
    const bounds = ref.current?.getBoundingClientRect() ?? { x: 0, width: 0 }
    return val - bounds.x - bounds.width / 2
  })

  const widthSync = useTransform(
    distanceVal,
    [-numDistance, 0, numDistance],
    [40, numMagnification, 40]
  )

  const width = useSpring(widthSync, {
    mass: 0.1,
    stiffness: 150,
    damping: 12,
  })

  return (
    <motion.div
      ref={ref}
      style={{ width }}
      className="group relative flex aspect-square cursor-pointer items-center justify-center rounded-full bg-muted/80 hover:bg-accent transition-colors"
      onClick={onClick}
      title={label}
    >
      <div className="flex items-center justify-center text-foreground">
        {icon}
      </div>
      <span className="absolute -top-8 left-1/2 -translate-x-1/2 rounded-md bg-popover px-2 py-1 text-xs text-popover-foreground border border-border opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap shadow-lg">
        {label}
      </span>
    </motion.div>
  )
}

file-upload.content:
"use client"

import * as React from "react"
import { motion, AnimatePresence } from "framer-motion"
import { UploadCloud, File, X, AlertCircle } from "lucide-react"
import { cn } from "../utils/cn"
import { Button } from "./button"

/**
 * Props for the FileUpload component
 */
export interface FileUploadProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSelect"> {
  /**
   * Callback fired when files are successfully validated and selected
   */
  onUpload: (files: File[]) => void
  /**
   * Accepted mime types or extensions, e.g. "image/*,application/pdf"
   */
  accept?: string
  /**
   * Maximum file size in bytes
   * @default 10 * 1024 * 1024 (10MB)
   */
  maxSize?: number
  /**
   * Whether to allow multiple file uploads
   * @default false
   */
  multiple?: boolean
  /**
   * Layout visual style
   * @default "default"
   */
  variant?: "default" | "dropzone" | "button"
  /**
   * Additional CSS classes
   */
  className?: string
}

/**
 * FileUpload component manages local file selection, validation, drag-and-drop state, and displays current uploads.
 */
const FileUpload = React.forwardRef<HTMLDivElement, FileUploadProps>(
  (
    {
      onUpload,
      accept,
      maxSize = 10 * 1024 * 1024,
      multiple = false,
      variant = "default",
      className,
      ...props
    },
    ref
  ) => {
    const fileInputRef = React.useRef<HTMLInputElement>(null)
    const [dragActive, setDragActive] = React.useState(false)
    const [selectedFiles, setSelectedFiles] = React.useState<File[]>([])
    const [error, setError] = React.useState<string | null>(null)

    const handleFiles = (files: FileList | null) => {
      if (!files) return
      setError(null)
      const validFiles: File[] = []
      
      const fileArray = Array.from(files)
      const limit = multiple ? fileArray.length : 1
      const filesToProcess = fileArray.slice(0, limit)

      for (const file of filesToProcess) {
        // Validate size
        if (file.size > maxSize) {
          setError(\`File "\${file.name}" exceeds the maximum allowed size of \${(maxSize / (1024 * 1024)).toFixed(0)}MB.\`)
          return
        }

        // Validate accept
        if (accept) {
          const acceptedTypes = accept.split(",").map(t => t.trim())
          const isAccepted = acceptedTypes.some((type) => {
            if (type.startsWith(".")) {
              return file.name.endsWith(type)
            }
            if (type.endsWith("/*")) {
              const baseType = type.split("/")[0]
              return file.type.startsWith(\`\${baseType}/\`)
            }
            return file.type === type
          })

          if (!isAccepted) {
            setError(\`File type for "\${file.name}" is not supported.\`)
            return
          }
        }

        validFiles.push(file)
      }

      if (validFiles.length > 0) {
        let updated: File[]
        if (multiple) {
          updated = [...selectedFiles, ...validFiles]
        } else {
          updated = validFiles
        }
        setSelectedFiles(updated)
        onUpload(updated)
      }
    }

    const handleDrag = (e: React.DragEvent) => {
      e.preventDefault()
      e.stopPropagation()
      if (e.type === "dragenter" || e.type === "dragover") {
        setDragActive(true)
      } else if (e.type === "dragleave") {
        setDragActive(false)
      }
    }

    const handleDrop = (e: React.DragEvent) => {
      e.preventDefault()
      e.stopPropagation()
      setDragActive(false)
      if (e.dataTransfer.files && e.dataTransfer.files[0]) {
        handleFiles(e.dataTransfer.files)
      }
    }

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      e.preventDefault()
      if (e.target.files && e.target.files[0]) {
        handleFiles(e.target.files)
      }
    }

    const removeFile = (idx: number) => {
      const updated = selectedFiles.filter((_, i) => i !== idx)
      setSelectedFiles(updated)
      onUpload(updated)
    }

    const triggerFileInput = () => {
      fileInputRef.current?.click()
    }

    return (
      <div ref={ref} className={cn("w-full space-y-4", className)} {...props}>
        <input
          ref={fileInputRef}
          type="file"
          accept={accept}
          multiple={multiple}
          onChange={handleChange}
          className="hidden"
        />

        {variant === "button" ? (
          <div className="flex flex-col sm:flex-row items-center justify-between gap-3 p-4 rounded-2xl border border-border/80 bg-card/60 backdrop-blur-md w-full">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary shrink-0">
                <UploadCloud className="h-5 w-5" />
              </div>
              <div className="text-left">
                <p className="text-sm font-semibold text-foreground">Select File{multiple ? "s" : ""}</p>
                <p className="text-xs text-muted-foreground">
                  {accept ? \`Supports: \${accept}\` : "Any file"} (Max: {(maxSize / (1024 * 1024)).toFixed(0)}MB)
                </p>
              </div>
            </div>
            <Button variant="default" onClick={triggerFileInput} className="flex items-center gap-2 shrink-0">
              <UploadCloud className="h-4 w-4" />
              <span>Browse Files</span>
            </Button>
          </div>
        ) : (
          <motion.div
            onDragEnter={handleDrag}
            onDragOver={handleDrag}
            onDragLeave={handleDrag}
            onDrop={handleDrop}
            onClick={triggerFileInput}
            className={cn(
              "relative flex flex-col items-center justify-center border-2 border-dashed rounded-2xl cursor-pointer transition-all duration-300 p-6 text-center select-none bg-muted/5",
              dragActive
                ? "border-primary bg-primary/5 scale-[1.01]"
                : "border-border hover:border-muted-foreground/40 hover:bg-muted/10",
              variant === "dropzone" ? "min-h-[220px]" : "min-h-[140px]"
            )}
            whileTap={{ scale: 0.99 }}
          >
            <div className="flex flex-col items-center justify-center gap-3">
              <div className="p-3 bg-muted/40 rounded-full border border-border group-hover:scale-110 transition-transform">
                <UploadCloud className="h-6 w-6 text-muted-foreground" />
              </div>
              <div className="space-y-1">
                <p className="text-sm font-semibold text-foreground">
                  Click to upload or drag & drop
                </p>
                <p className="text-xs text-muted-foreground">
                  {accept ? \`Supports: \${accept}\` : "All files supported"} (Max: {(maxSize / (1024 * 1024)).toFixed(0)}MB)
                </p>
              </div>
            </div>
          </motion.div>
        )}

        {/* Error messaging */}
        <AnimatePresence mode="wait">
          {error && (
            <motion.div
              initial={{ opacity: 0, y: -5 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -5 }}
              className="flex items-center gap-2 text-xs text-destructive bg-destructive/10 border border-destructive/20 rounded-lg p-3"
            >
              <AlertCircle className="h-4 w-4 shrink-0" />
              <span>{error}</span>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Selected file preview tags */}
        <AnimatePresence>
          {selectedFiles.length > 0 && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="border border-border/60 rounded-xl divide-y divide-border/40 overflow-hidden"
            >
              {selectedFiles.map((file, idx) => (
                <motion.div
                  key={file.name + idx}
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={{ opacity: 0, height: 0 }}
                  className="flex items-center justify-between p-3 text-sm bg-card"
                >
                  <div className="flex items-center gap-2.5 min-w-0">
                    <File className="h-4 w-4 text-primary shrink-0" />
                    <div className="min-w-0 flex flex-col text-left">
                      <span className="font-medium text-foreground truncate max-w-[280px]">
                        {file.name}
                      </span>
                      <span className="text-[10px] text-muted-foreground">
                        {(file.size / 1024).toFixed(0)} KB
                      </span>
                    </div>
                  </div>
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={(e) => {
                      e.stopPropagation()
                      removeFile(idx)
                    }}
                    className="h-7 w-7 rounded-lg text-muted-foreground/60 hover:text-foreground"
                  >
                    <X className="h-4 w-4" />
                  </Button>
                </motion.div>
              ))}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    )
  }
)

FileUpload.displayName = "FileUpload"

export { FileUpload }

frost-hover-card.content:
"use client";

import * as React from "react";
import { useState, useRef, useEffect, useCallback, useId } from "react";
import { cn } from "../utils/cn";
import { Eye, EyeOff, Droplets } from "lucide-react";

export interface FrostHoverCardProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Transparent PNG image URL of the product or object.
   */
  src: string;
  /**
   * Card title or product name.
   */
  title?: string;
  /**
   * Secondary label or subtitle.
   */
  subtitle?: string;
  /**
   * Optional price string.
   */
  price?: string;
  /**
   * Badge text displayed at top of card.
   */
  badge?: string;
  /**
   * Card width in pixels or CSS dimension string.
   * @default 360
   */
  cardWidth?: number | string;
  /**
   * Card height in pixels or CSS dimension string.
   * @default 480
   */
  cardHeight?: number | string;
  /**
   * Radius in pixels of the wiped clear circular viewport under the cursor.
   * @default 110
   */
  wipeRadius?: number;
  /**
   * Backdrop blur strength in pixels applied to the steamed glass layer.
   * @default 16
   */
  blurAmount?: number;
}

/**
 * FrostHoverCard
 *
 * Luxury product showcase card concealed behind a steamed frosted glass overlay.
 * Moving the cursor dynamically wipes away the frost with realistic radial gradient
 * mask physics, and smoothly steams back up once the pointer departs.
 */
export const FrostHoverCard = React.forwardRef<HTMLDivElement, FrostHoverCardProps>(
  (
    {
      src,
      title = "Aero Stealth H1",
      subtitle = "CONDENSATION SEALED • ACTIVE ANC",
      price = "$780",
      badge = "Frosted Vapor",
      cardWidth = 360,
      cardHeight = 480,
      wipeRadius = 110,
      blurAmount = 16,
      className,
      style,
      ...props
    },
    ref
  ) => {
    const cardId = useId();
    const containerRef = useRef<HTMLDivElement>(null);
    const frostLayerRef = useRef<HTMLDivElement>(null);

    const targetRadiusRef = useRef(0);
    const currRadiusRef = useRef(0);
    const animFrameRef = useRef<number | null>(null);

    const [isForceWiped, setIsForceWiped] = useState(false);
    const [wipePercent, setWipePercent] = useState(0);

    // Physics Animation Loop for Frost Hole Smooth Growth & Decay
    useEffect(() => {
      let isRunning = true;

      const physicsLoop = () => {
        if (!isRunning) return;

        const effectiveTarget = isForceWiped ? 1200 : targetRadiusRef.current;
        const delta = effectiveTarget - currRadiusRef.current;

        // Smooth spring/lerp easing for radius
        currRadiusRef.current += delta * 0.16;

        if (frostLayerRef.current) {
          const r = Math.max(0, currRadiusRef.current);
          frostLayerRef.current.style.setProperty("--r", `${r.toFixed(1)}px`);
        }

        const pct = isForceWiped
          ? 100
          : Math.min(100, Math.max(0, Math.round((currRadiusRef.current / wipeRadius) * 100)));
        setWipePercent(pct);

        animFrameRef.current = requestAnimationFrame(physicsLoop);
      };

      animFrameRef.current = requestAnimationFrame(physicsLoop);

      return () => {
        isRunning = false;
        if (animFrameRef.current) {
          cancelAnimationFrame(animFrameRef.current);
        }
      };
    }, [isForceWiped, wipeRadius]);

    // Pointer Wipe Handlers
    const handlePointerMove = useCallback(
      (e: React.PointerEvent<HTMLDivElement>) => {
        if (!containerRef.current || isForceWiped) return;
        const rect = containerRef.current.getBoundingClientRect();

        const x = Math.max(0, Math.min(rect.width, e.clientX - rect.left));
        const y = Math.max(0, Math.min(rect.height, e.clientY - rect.top));

        const xPct = (x / rect.width) * 100;
        const yPct = (y / rect.height) * 100;

        if (frostLayerRef.current) {
          frostLayerRef.current.style.setProperty("--mx", `${xPct.toFixed(1)}%`);
          frostLayerRef.current.style.setProperty("--my", `${yPct.toFixed(1)}%`);
        }

        targetRadiusRef.current = wipeRadius;
      },
      [isForceWiped, wipeRadius]
    );

    const handlePointerLeave = useCallback(() => {
      if (!isForceWiped) {
        targetRadiusRef.current = 0;
      }
    }, [isForceWiped]);

    return (
      <div
        ref={ref}
        className={cn("group flex flex-col items-center select-none", className)}
        style={{
          width: typeof cardWidth === "number" ? `${cardWidth}px` : cardWidth,
          ...style,
        }}
        {...props}
      >
        <div
          ref={containerRef}
          onPointerMove={handlePointerMove}
          onPointerLeave={handlePointerLeave}
          className="relative w-full rounded-2xl p-5 border border-white/10 bg-[hsl(225_12%_7%)] hover:border-white/20 transition-all duration-300 shadow-2xl overflow-hidden flex flex-col justify-between cursor-crosshair"
          style={{
            minHeight: typeof cardHeight === "number" ? `${cardHeight}px` : cardHeight,
          }}
        >
          {/* Subtle Backstage Ambient Atmosphere */}
          <div className="absolute -top-24 left-1/4 w-72 h-72 bg-sky-500/10 rounded-full blur-3xl pointer-events-none" />
          <div className="absolute -bottom-24 right-1/4 w-72 h-72 bg-emerald-500/10 rounded-full blur-3xl pointer-events-none" />

          {/* Base Product Visual */}
          <div className="absolute inset-0 flex items-center justify-center p-8 pointer-events-none select-none">
            <img
              src={src}
              alt={title}
              className="max-w-full max-h-[260px] object-contain drop-shadow-[0_20px_40px_rgba(0,0,0,0.7)] transform transition-transform duration-500 group-hover:scale-105"
            />
          </div>

          {/* Steamed / Frosted Glass Overlay with dynamic mask hole */}
          <div
            ref={frostLayerRef}
            className="absolute inset-0 pointer-events-none z-10 transition-[backdrop-filter] duration-300"
            style={{
              backdropFilter: `blur(${blurAmount}px) saturate(125%)`,
              WebkitBackdropFilter: `blur(${blurAmount}px) saturate(125%)`,
              backgroundColor: "rgba(9, 11, 16, 0.52)",
              maskImage:
                "radial-gradient(circle at var(--mx, 50%) var(--my, 50%), transparent 0px, transparent var(--r, 0px), black calc(var(--r, 0px) + 55px))",
              WebkitMaskImage:
                "radial-gradient(circle at var(--mx, 50%) var(--my, 50%), transparent 0px, transparent var(--r, 0px), black calc(var(--r, 0px) + 55px))",
            }}
          >
            {/* Fine Condensation Droplets Texture Grid */}
            <div
              className="absolute inset-0 opacity-20 mix-blend-overlay pointer-events-none"
              style={{
                backgroundImage:
                  "radial-gradient(circle at 50% 50%, rgba(255,255,255,0.4) 1px, transparent 1px), radial-gradient(circle at 20% 30%, rgba(255,255,255,0.2) 2px, transparent 2px), radial-gradient(circle at 80% 70%, rgba(255,255,255,0.25) 1.5px, transparent 1.5px)",
                backgroundSize: "28px 28px, 48px 48px, 36px 36px",
              }}
            />

            {/* Steamy Vignette Edge */}
            <div
              className="absolute inset-0 pointer-events-none"
              style={{
                background:
                  "radial-gradient(ellipse 90% 90% at 50% 50%, transparent 60%, rgba(9,11,16,0.4) 100%)",
              }}
            />
          </div>

          {/* Top Header Plate */}
          <div className="relative z-20 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse" />
              <span className="text-[11px] font-mono font-semibold uppercase tracking-wider text-emerald-400/90">
                {badge}
              </span>
            </div>

            {/* Force Wipe Toggle */}
            <button
              type="button"
              onClick={() => setIsForceWiped(!isForceWiped)}
              className="flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-[10px] font-mono text-zinc-300 hover:text-white bg-white/5 hover:bg-white/10 border border-white/8 transition-all cursor-pointer active:scale-95"
              title="Toggle full glass wipe"
            >
              {isForceWiped ? (
                <>
                  <EyeOff className="w-3 h-3 text-cyan-400" />
                  <span>Steam Up</span>
                </>
              ) : (
                <>
                  <Eye className="w-3 h-3 text-emerald-400" />
                  <span>Wipe All</span>
                </>
              )}
            </button>
          </div>

          {/* Center Hint (Fades when wiped) */}
          <div
            className="relative z-20 my-auto pointer-events-none text-center transition-opacity duration-300"
            style={{ opacity: wipePercent > 35 ? 0 : 0.8 }}
          >
            <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-black/40 border border-white/10 backdrop-blur-md text-[10px] font-mono text-zinc-400">
              <Droplets className="w-3 h-3 text-cyan-400 animate-pulse" />
              <span>Hover to wipe condensation</span>
            </div>
          </div>

          {/* Bottom Card Typographic Plate */}
          <div className="relative z-20 border-t border-white/8 pt-4">
            <div className="flex items-baseline justify-between mb-1">
              <h3 className="text-base font-semibold text-white tracking-tight">
                {title}
              </h3>
              {price && (
                <span className="text-sm font-mono font-bold text-emerald-400">
                  {price}
                </span>
              )}
            </div>

            <div className="flex items-center justify-between">
              <p className="text-xs text-zinc-400 font-mono tracking-wide">
                {subtitle}
              </p>
              <span className="text-[10px] font-mono text-zinc-500">
                {isForceWiped ? "100% Clear" : `${wipePercent}% Wiped`}
              </span>
            </div>
          </div>
        </div>
      </div>
    );
  }
);

FrostHoverCard.displayName = "FrostHoverCard";

glass-shatter-card.content:
"use client";

import * as React from "react";
import { useState, useRef, useEffect, useCallback, useId } from "react";
import { cn } from "../utils/cn";
import { Zap, RotateCcw } from "lucide-react";

export interface GlassShatterCardProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Transparent PNG image URL of the product or object.
   */
  src: string;
  /**
   * Card title or product name.
   */
  title?: string;
  /**
   * Secondary label or subtitle.
   */
  subtitle?: string;
  /**
   * Optional price string.
   */
  price?: string;
  /**
   * Badge text displayed at top of card.
   */
  badge?: string;
  /**
   * Card width in pixels or CSS dimension string.
   * @default 360
   */
  cardWidth?: number | string;
  /**
   * Card height in pixels or CSS dimension string.
   * @default 480
   */
  cardHeight?: number | string;
  /**
   * Number of grid columns for triangular glass shard subdivision.
   * @default 5
   */
  gridCols?: number;
  /**
   * Number of grid rows for triangular glass shard subdivision.
   * @default 6
   */
  gridRows?: number;
  /**
   * Jitter displacement factor for jagged internal vertices (0.1 to 0.45).
   * @default 0.35
   */
  jitterAmount?: number;
  /**
   * Explosion impulse force magnitude on click.
   * @default 11
   */
  shatterForce?: number;
  /**
   * Downward gravitational acceleration acting on floating shards.
   * @default 0.36
   */
  gravity?: number;
  /**
   * Delay in milliseconds before shards automatically spring back together.
   * @default 1600
   */
  autoRestoreDelay?: number;
}

interface Point {
  x: number;
  y: number;
}

interface Shard {
  p0: Point;
  p1: Point;
  p2: Point;
  cx: number;
  cy: number;
  x: number;
  y: number;
  rot: number;
  vx: number;
  vy: number;
  vrot: number;
}

/**
 * GlassShatterCard
 *
 * Luxury showcase card where the product is subdivided into an irregular watertight
 * mesh of glass shards with zero gaps at rest. Clicking triggers an explosive shatter
 * with gravity and rotation physics, followed by an organic spring return.
 */
export const GlassShatterCard = React.forwardRef<HTMLDivElement, GlassShatterCardProps>(
  (
    {
      src,
      title = "Prism Chronometer",
      subtitle = "SHATTERED SAPPHIRE CRYSTAL",
      price = "$1,890",
      badge = "Glass Physics",
      cardWidth = 360,
      cardHeight = 480,
      gridCols = 5,
      gridRows = 6,
      jitterAmount = 0.35,
      shatterForce = 11,
      gravity = 0.36,
      autoRestoreDelay = 1600,
      className,
      style,
      ...props
    },
    ref
  ) => {
    const cardId = useId();
    const containerRef = useRef<HTMLDivElement>(null);
    const canvasRef = useRef<HTMLCanvasElement | null>(null);
    const imageRef = useRef<HTMLImageElement | null>(null);
    const shardsRef = useRef<Shard[]>([]);
    const animFrameRef = useRef<number | null>(null);
    const restoreTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    const isShatteredRef = useRef(false);
    const isReturningRef = useRef(false);
    const [isShatteredState, setIsShatteredState] = useState(false);
    const [isLoaded, setIsLoaded] = useState(false);

    // Build watertight jagged shard mesh
    const buildMesh = useCallback(
      (width: number, height: number, dpr: number) => {
        const cols = Math.max(3, gridCols);
        const rows = Math.max(3, gridRows);
        const cellW = width / cols;
        const cellH = height / rows;

        // 1. Generate grid vertices with shared interior jitter
        const vertices: Point[][] = [];
        for (let r = 0; r <= rows; r++) {
          vertices[r] = [];
          for (let c = 0; c <= cols; c++) {
            let vx = c * cellW;
            let vy = r * cellH;

            // Apply jitter only to interior vertices to keep rectangular outer boundaries watertight
            if (c > 0 && c < cols && r > 0 && r < rows) {
              const jx = (Math.random() - 0.5) * cellW * jitterAmount;
              const jy = (Math.random() - 0.5) * cellH * jitterAmount;
              vx += jx;
              vy += jy;
            }

            vertices[r][c] = { x: vx * dpr, y: vy * dpr };
          }
        }

        // 2. Generate triangular shards with shared vertices
        const shards: Shard[] = [];
        for (let r = 0; r < rows; r++) {
          for (let c = 0; c < cols; c++) {
            const p00 = vertices[r][c];
            const p10 = vertices[r][c + 1];
            const p11 = vertices[r + 1][c + 1];
            const p01 = vertices[r + 1][c];

            const alternateDiag = (r + c) % 2 === 0;

            if (alternateDiag) {
              // Diagonal from p00 to p11
              const t1_cx = (p00.x + p10.x + p11.x) / 3;
              const t1_cy = (p00.y + p10.y + p11.y) / 3;
              shards.push({
                p0: p00,
                p1: p10,
                p2: p11,
                cx: t1_cx,
                cy: t1_cy,
                x: 0,
                y: 0,
                rot: 0,
                vx: 0,
                vy: 0,
                vrot: 0,
              });

              const t2_cx = (p00.x + p11.x + p01.x) / 3;
              const t2_cy = (p00.y + p11.y + p01.y) / 3;
              shards.push({
                p0: p00,
                p1: p11,
                p2: p01,
                cx: t2_cx,
                cy: t2_cy,
                x: 0,
                y: 0,
                rot: 0,
                vx: 0,
                vy: 0,
                vrot: 0,
              });
            } else {
              // Diagonal from p10 to p01
              const t1_cx = (p00.x + p10.x + p01.x) / 3;
              const t1_cy = (p00.y + p10.y + p01.y) / 3;
              shards.push({
                p0: p00,
                p1: p10,
                p2: p01,
                cx: t1_cx,
                cy: t1_cy,
                x: 0,
                y: 0,
                rot: 0,
                vx: 0,
                vy: 0,
                vrot: 0,
              });

              const t2_cx = (p10.x + p11.x + p01.x) / 3;
              const t2_cy = (p10.y + p11.y + p01.y) / 3;
              shards.push({
                p0: p10,
                p1: p11,
                p2: p01,
                cx: t2_cx,
                cy: t2_cy,
                x: 0,
                y: 0,
                rot: 0,
                vx: 0,
                vy: 0,
                vrot: 0,
              });
            }
          }
        }

        shardsRef.current = shards;
      },
      [gridCols, gridRows, jitterAmount]
    );

    // Load Image
    useEffect(() => {
      if (!src) return;
      let cancelled = false;
      setIsLoaded(false);

      const img = new Image();
      img.crossOrigin = "anonymous";
      img.src = src;

      img.onload = () => {
        if (cancelled) return;
        imageRef.current = img;

        const canvas = canvasRef.current;
        if (!canvas) return;

        const dpr = typeof window !== "undefined" ? Math.min(window.devicePixelRatio || 1, 2) : 1;
        const displayW = canvas.clientWidth || 320;
        const displayH = canvas.clientHeight || 280;

        canvas.width = displayW * dpr;
        canvas.height = displayH * dpr;

        buildMesh(displayW, displayH, dpr);
        setIsLoaded(true);
      };

      return () => {
        cancelled = true;
      };
    }, [src, buildMesh]);

    // Shatter explosion trigger
    const triggerShatter = useCallback(
      (clientX?: number, clientY?: number) => {
        const canvas = canvasRef.current;
        if (!canvas || !imageRef.current) return;

        if (restoreTimerRef.current) {
          clearTimeout(restoreTimerRef.current);
        }

        const rect = canvas.getBoundingClientRect();
        const dpr = typeof window !== "undefined" ? Math.min(window.devicePixelRatio || 1, 2) : 1;

        const clickX = clientX !== undefined ? (clientX - rect.left) * dpr : canvas.width / 2;
        const clickY = clientY !== undefined ? (clientY - rect.top) * dpr : canvas.height / 2;

        const shards = shardsRef.current;
        const force = shatterForce * dpr;

        for (let i = 0; i < shards.length; i++) {
          const s = shards[i];
          const dx = s.cx - clickX;
          const dy = s.cy - clickY;
          const dist = Math.sqrt(dx * dx + dy * dy) + 1;

          const impulse = (force * (0.8 + Math.random() * 0.6)) / Math.max(1, dist * 0.015);
          s.vx = (dx / dist) * impulse + (Math.random() - 0.5) * 5 * dpr;
          s.vy = (dy / dist) * impulse - (3 + Math.random() * 7) * dpr;
          s.vrot = (Math.random() - 0.5) * 0.32;
        }

        isShatteredRef.current = true;
        isReturningRef.current = false;
        setIsShatteredState(true);

        // Schedule organic spring return
        restoreTimerRef.current = setTimeout(() => {
          isReturningRef.current = true;
        }, autoRestoreDelay);
      },
      [shatterForce, autoRestoreDelay]
    );

    // Canvas Physics Animation Loop
    useEffect(() => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;

      let isRunning = true;

      const render = () => {
        if (!isRunning) return;

        const img = imageRef.current;
        const shards = shardsRef.current;
        const dpr = typeof window !== "undefined" ? Math.min(window.devicePixelRatio || 1, 2) : 1;

        ctx.clearRect(0, 0, canvas.width, canvas.height);

        if (img && isLoaded && shards.length > 0) {
          // Scale image to fit canvas proportionally with margins
          const padding = 20 * dpr;
          const maxW = canvas.width - padding * 2;
          const maxH = canvas.height - padding * 2;
          const scale = Math.min(maxW / img.width, maxH / img.height);
          const drawW = img.width * scale;
          const drawH = img.height * scale;
          const offsetX = (canvas.width - drawW) / 2;
          const offsetY = (canvas.height - drawH) / 2;

          let allSettled = true;
          const grav = gravity * dpr;

          for (let i = 0; i < shards.length; i++) {
            const s = shards[i];

            // 1. Physics Integration
            if (isShatteredRef.current) {
              if (isReturningRef.current) {
                // Spring pull towards origin (0, 0, 0)
                const springStiffness = 0.09;
                const springDamping = 0.85;

                s.vx += (0 - s.x) * springStiffness;
                s.vy += (0 - s.y) * springStiffness;
                s.vrot += (0 - s.rot) * springStiffness;

                s.vx *= springDamping;
                s.vy *= springDamping;
                s.vrot *= springDamping;

                s.x += s.vx;
                s.y += s.vy;
                s.rot += s.vrot;

                if (
                  Math.abs(s.x) > 0.3 ||
                  Math.abs(s.y) > 0.3 ||
                  Math.abs(s.rot) > 0.01
                ) {
                  allSettled = false;
                } else {
                  s.x = 0;
                  s.y = 0;
                  s.rot = 0;
                  s.vx = 0;
                  s.vy = 0;
                  s.vrot = 0;
                }
              } else {
                // Explosive flight with gravity
                s.vy += grav;
                s.vx *= 0.985;
                s.x += s.vx;
                s.y += s.vy;
                s.rot += s.vrot;
                allSettled = false;
              }
            }

            // 2. Render Shard
            ctx.save();
            ctx.translate(s.cx + s.x, s.cy + s.y);
            if (s.rot !== 0) {
              ctx.rotate(s.rot);
            }

            ctx.beginPath();
            ctx.moveTo(s.p0.x - s.cx, s.p0.y - s.cy);
            ctx.lineTo(s.p1.x - s.cx, s.p1.y - s.cy);
            ctx.lineTo(s.p2.x - s.cx, s.p2.y - s.cy);
            ctx.closePath();

            ctx.clip();
            ctx.drawImage(img, offsetX - s.cx, offsetY - s.cy, drawW, drawH);

            // Shard reflection highlight edge when detached
            if (s.x !== 0 || s.y !== 0) {
              ctx.strokeStyle = "rgba(255, 255, 255, 0.35)";
              ctx.lineWidth = 1 * dpr;
              ctx.stroke();
            }

            ctx.restore();
          }

          if (isShatteredRef.current && isReturningRef.current && allSettled) {
            isShatteredRef.current = false;
            isReturningRef.current = false;
            setIsShatteredState(false);
          }
        }

        animFrameRef.current = requestAnimationFrame(render);
      };

      animFrameRef.current = requestAnimationFrame(render);

      return () => {
        isRunning = false;
        if (animFrameRef.current) {
          cancelAnimationFrame(animFrameRef.current);
        }
      };
    }, [gravity, isLoaded]);

    return (
      <div
        ref={ref}
        className={cn("group flex flex-col items-center select-none", className)}
        style={{
          width: typeof cardWidth === "number" ? `${cardWidth}px` : cardWidth,
          ...style,
        }}
        {...props}
      >
        <div
          ref={containerRef}
          onClick={(e) => triggerShatter(e.clientX, e.clientY)}
          className="relative w-full rounded-2xl p-5 border border-white/10 bg-[hsl(225_12%_7%)] hover:border-amber-400/30 transition-all duration-300 shadow-2xl overflow-hidden flex flex-col justify-between cursor-pointer"
          style={{
            minHeight: typeof cardHeight === "number" ? `${cardHeight}px` : cardHeight,
          }}
        >
          {/* Subtle Ambient Radial Glow */}
          <div className="absolute -top-24 right-0 w-64 h-64 bg-amber-500/10 rounded-full blur-3xl pointer-events-none" />
          <div className="absolute -bottom-24 left-0 w-64 h-64 bg-rose-500/10 rounded-full blur-3xl pointer-events-none" />

          {/* Top Header Plate */}
          <div className="relative z-10 flex items-center justify-between pointer-events-none">
            <div className="flex items-center gap-2">
              <span className="w-1.5 h-1.5 rounded-full bg-amber-400 animate-pulse" />
              <span className="text-[11px] font-mono font-semibold uppercase tracking-wider text-amber-400/90">
                {badge}
              </span>
            </div>

            <div className="flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-[10px] font-mono text-zinc-400 bg-white/5 border border-white/8">
              <Zap className="w-3 h-3 text-amber-400" />
              <span>{isShatteredState ? "Shattered" : "Click to Shatter"}</span>
            </div>
          </div>

          {/* Center Stage: Interactive Shard Canvas */}
          <div className="relative w-full h-[260px] my-auto flex items-center justify-center">
            <canvas
              ref={canvasRef}
              className="w-full h-full"
            />
          </div>

          {/* Bottom Card Typographic Plate */}
          <div className="relative z-10 border-t border-white/8 pt-4 pointer-events-none">
            <div className="flex items-baseline justify-between mb-1">
              <h3 className="text-base font-semibold text-white tracking-tight">
                {title}
              </h3>
              {price && (
                <span className="text-sm font-mono font-bold text-amber-400">
                  {price}
                </span>
              )}
            </div>

            <div className="flex items-center justify-between">
              <p className="text-xs text-zinc-400 font-mono tracking-wide">
                {subtitle}
              </p>
              <span className="text-[10px] font-mono text-zinc-500">
                {gridCols * gridRows * 2} shards
              </span>
            </div>
          </div>
        </div>
      </div>
    );
  }
);

GlassShatterCard.displayName = "GlassShatterCard";

holo-finish-card.content:
"use client";

import * as React from "react";
import { useState, useRef, useEffect, useCallback, useMemo } from "react";
import { cn } from "../utils/cn";

export interface ProductFinishItem {
  id: string;
  name: string;
  label?: string;
  image: string;
  holoColors: string[];
  price?: string;
  description?: string;
}

export type HoloFinishIntensity = "subtle" | "medium" | "vibrant";

export interface HoloFinishCardProps extends React.HTMLAttributes<HTMLDivElement> {
  finishes: ProductFinishItem[];
  selectedFinishId?: string;
  onSelectFinish?: (finish: ProductFinishItem) => void;
  cardWidth?: number | string;
  cardHeight?: number | string;
  intensity?: HoloFinishIntensity;
  showLabels?: boolean;
  maxTilt?: number;
  perspective?: number;
  elevateZ?: number;
  idleAnimation?: boolean;
  showGlare?: boolean;
  showSwatches?: boolean;
}

export const HoloFinishCard = React.forwardRef<HTMLDivElement, HoloFinishCardProps>(
  (
    {
      finishes,
      selectedFinishId,
      onSelectFinish,
      cardWidth = 360,
      cardHeight = 480,
      intensity = "medium",
      showLabels = true,
      maxTilt = 32,
      perspective = 900,
      elevateZ = 45,
      idleAnimation = true,
      showGlare = true,
      showSwatches = true,
      className,
      style,
      ...props
    },
    ref
  ) => {
    const [internalSelectedId, setInternalSelectedId] = useState<string>(() => {
      return selectedFinishId || (finishes.length > 0 ? finishes[0].id : "");
    });

    const activeId = selectedFinishId ?? internalSelectedId;
    const activeFinish = useMemo(() => {
      const found = finishes.find((f) => f.id === activeId);
      return found || finishes[0] || null;
    }, [finishes, activeId]);

    const handleSelect = useCallback(
      (finish: ProductFinishItem) => {
        if (!selectedFinishId) {
          setInternalSelectedId(finish.id);
        }
        onSelectFinish?.(finish);
      },
      [selectedFinishId, onSelectFinish]
    );

    const containerRef = useRef<HTMLDivElement>(null);
    const cardRef = useRef<HTMLDivElement>(null);
    const foilRef = useRef<HTMLDivElement>(null);
    const glareRef = useRef<HTMLDivElement>(null);

    const rectRef = useRef<DOMRect | null>(null);
    const isHoveringRef = useRef(false);
    const targetPointerRef = useRef({ x: 0.5, y: 0.5 });
    const animFrameRef = useRef<number | null>(null);

    const currentPhysicsRef = useRef({
      rotateX: 0,
      rotateY: 0,
      scale: 1,
      holoX: 50,
      holoY: 50,
      glareX: 50,
      glareY: 50,
      glareAlpha: 0,
    });

    const foilOpacity = useMemo(() => {
      switch (intensity) {
        case "subtle":
          return 0.38;
        case "vibrant":
          return 0.85;
        case "medium":
        default:
          return 0.62;
      }
    }, [intensity]);

    const updateRect = useCallback(() => {
      if (cardRef.current) {
        rectRef.current = cardRef.current.getBoundingClientRect();
      }
    }, []);

    const handlePointerEnter = useCallback(
      (e: React.PointerEvent<HTMLDivElement>) => {
        updateRect();
        isHoveringRef.current = true;
        if (rectRef.current) {
          const px = Math.max(0, Math.min(1, (e.clientX - rectRef.current.left) / rectRef.current.width));
          const py = Math.max(0, Math.min(1, (e.clientY - rectRef.current.top) / rectRef.current.height));
          targetPointerRef.current = { x: px, y: py };
        }
      },
      [updateRect]
    );

    const handlePointerMove = useCallback((e: React.PointerEvent<HTMLDivElement>) => {
      if (!rectRef.current && cardRef.current) {
        rectRef.current = cardRef.current.getBoundingClientRect();
      }
      if (rectRef.current && rectRef.current.width > 0 && rectRef.current.height > 0) {
        const px = Math.max(0, Math.min(1, (e.clientX - rectRef.current.left) / rectRef.current.width));
        const py = Math.max(0, Math.min(1, (e.clientY - rectRef.current.top) / rectRef.current.height));
        targetPointerRef.current = { x: px, y: py };
      }
    }, []);

    const handlePointerLeave = useCallback(() => {
      isHoveringRef.current = false;
      targetPointerRef.current = { x: 0.5, y: 0.5 };
    }, []);

    useEffect(() => {
      const onResize = () => {
        updateRect();
      };
      window.addEventListener("resize", onResize, { passive: true });
      return () => {
        window.removeEventListener("resize", onResize);
      };
    }, [updateRect]);

    useEffect(() => {
      let isMounted = true;

      const loop = (timestamp: number) => {
        if (!isMounted) return;

        const card = cardRef.current;
        const foil = foilRef.current;
        const glare = glareRef.current;
        const p = currentPhysicsRef.current;

        let targetRotX = 0;
        let targetRotY = 0;
        let targetScale = 1;
        let targetHX = 50;
        let targetHY = 50;
        let targetGX = 50;
        let targetGY = 50;
        let targetGA = 0;

        if (isHoveringRef.current) {
          const px = targetPointerRef.current.x;
          const py = targetPointerRef.current.y;

          targetRotY = (px - 0.5) * maxTilt;
          targetRotX = -(py - 0.5) * maxTilt;
          targetScale = 1.025;

          targetHX = px * 100;
          targetHY = py * 100;

          targetGX = px * 100;
          targetGY = py * 100;
          targetGA = intensity === "subtle" ? 0.35 : intensity === "vibrant" ? 0.75 : 0.55;
        } else if (idleAnimation) {
          const time = timestamp * 0.0015;
          targetRotX = Math.sin(time) * 2.5;
          targetRotY = Math.cos(time * 0.8) * 2.5;
          targetScale = 1;

          targetHX = 50 + Math.sin(time * 1.2) * 35;
          targetHY = 50 + Math.cos(time * 0.9) * 35;

          targetGX = 50 + Math.sin(time * 1.2) * 30;
          targetGY = 50 + Math.cos(time * 0.9) * 30;
          targetGA = 0.22;
        } else {
          targetRotX = 0;
          targetRotY = 0;
          targetScale = 1;
          targetHX = 50;
          targetHY = 50;
          targetGX = 50;
          targetGY = 50;
          targetGA = 0;
        }

        const lerpFactor = isHoveringRef.current ? 0.09 : 0.05;
        p.rotateX += (targetRotX - p.rotateX) * lerpFactor;
        p.rotateY += (targetRotY - p.rotateY) * lerpFactor;
        p.scale += (targetScale - p.scale) * lerpFactor;
        p.holoX += (targetHX - p.holoX) * lerpFactor;
        p.holoY += (targetHY - p.holoY) * lerpFactor;
        p.glareX += (targetGX - p.glareX) * lerpFactor;
        p.glareY += (targetGY - p.glareY) * lerpFactor;
        p.glareAlpha += (targetGA - p.glareAlpha) * lerpFactor;

        if (card) {
          card.style.transform = \`rotateX(\${p.rotateX.toFixed(2)}deg) rotateY(\${p.rotateY.toFixed(2)}deg) scale3d(\${p.scale.toFixed(3)}, \${p.scale.toFixed(3)}, \${p.scale.toFixed(3)})\`;
        }

        if (foil) {
          foil.style.backgroundPosition = \`\${p.holoX.toFixed(1)}% \${p.holoY.toFixed(1)}%\`;
        }

        if (glare && showGlare) {
          glare.style.background = \`radial-gradient(circle at \${p.glareX.toFixed(1)}% \${p.glareY.toFixed(1)}%, rgba(255,255,255,\${p.glareAlpha.toFixed(2)}) 0%, rgba(255,255,255,\${(p.glareAlpha * 0.35).toFixed(2)}) 22%, transparent 60%)\`;
        }

        animFrameRef.current = requestAnimationFrame(loop);
      };

      animFrameRef.current = requestAnimationFrame(loop);

      return () => {
        isMounted = false;
        if (animFrameRef.current) {
          cancelAnimationFrame(animFrameRef.current);
        }
      };
    }, [maxTilt, idleAnimation, intensity, showGlare]);

    if (!activeFinish) {
      return null;
    }

    const widthStyle = typeof cardWidth === "number" ? \`\${cardWidth}px\` : cardWidth;
    const heightStyle = typeof cardHeight === "number" ? \`\${cardHeight}px\` : cardHeight;
    const primaryFinishColor = activeFinish.holoColors[0] || "#ffffff";
    const finishGradientString = activeFinish.holoColors.join(", ");

    return (
      <div
        ref={ref}
        className={cn("flex flex-col items-center select-none", className)}
        style={{
          width: widthStyle,
          ...style,
        }}
        {...props}
      >
        <div
          ref={containerRef}
          className="relative w-full"
          style={{
            height: heightStyle,
            perspective: \`\${perspective}px\`,
          }}
          onPointerEnter={handlePointerEnter}
          onPointerMove={handlePointerMove}
          onPointerLeave={handlePointerLeave}
        >
          <div
            ref={cardRef}
            className={cn(
              "relative w-full h-full rounded-3xl overflow-hidden cursor-pointer",
              "border border-black/[0.08] dark:border-white/[0.12]",
              "bg-gradient-to-b from-white via-slate-50 to-slate-100",
              "dark:from-[#151821] dark:via-[#0e1017] dark:to-[#090b10]",
              "shadow-[0_20px_50px_-15px_rgba(0,0,0,0.12),0_0_0_1px_rgba(0,0,0,0.04)]",
              "dark:shadow-[0_25px_60px_-15px_rgba(0,0,0,0.7),0_0_0_1px_rgba(255,255,255,0.06),inset_0_1px_0_0_rgba(255,255,255,0.12)]",
              "transition-shadow duration-300"
            )}
            style={{
              transformStyle: "preserve-3d",
              willChange: "transform",
              touchAction: "pan-y",
            }}
            onClick={() => handleSelect(activeFinish)}
          >
            <div
              className="absolute inset-0 pointer-events-none transition-colors duration-700 opacity-20 dark:opacity-25"
              style={{
                background: \`radial-gradient(circle at 50% 50%, \${primaryFinishColor} 0%, transparent 65%)\`,
              }}
            />

            <div className="absolute inset-0 bg-[linear-gradient(to_right,rgba(0,0,0,0.02)_1px,transparent_1px),linear-gradient(to_bottom,rgba(0,0,0,0.02)_1px,transparent_1px)] dark:bg-[linear-gradient(to_right,rgba(255,255,255,0.02)_1px,transparent_1px),linear-gradient(to_bottom,rgba(255,255,255,0.02)_1px,transparent_1px)] bg-[size:24px_24px] pointer-events-none" />

            {showGlare && (
              <div
                ref={glareRef}
                className="absolute inset-0 pointer-events-none rounded-3xl"
                style={{
                  mixBlendMode: "overlay",
                  zIndex: 20,
                }}
              />
            )}

            {showLabels && (
              <div
                className="absolute top-0 inset-x-0 p-5 sm:p-6 flex items-start justify-between pointer-events-none z-10"
                style={{
                  transform: "translateZ(28px)",
                  transformStyle: "preserve-3d",
                }}
              >
                <div className="space-y-0.5">
                  <span className="text-[10px] font-mono uppercase tracking-widest text-slate-500 dark:text-slate-400 font-semibold">
                    {activeFinish.label || "FINISH SPEC"}
                  </span>
                  <div className="flex items-center gap-1.5">
                    <span
                      className="w-2 h-2 rounded-full shadow-xs"
                      style={{
                        backgroundColor: primaryFinishColor,
