node-flow-graph.content:
'use client';

import * as React from 'react';
import { motion } from 'framer-motion';
import { Play, RotateCcw, CheckCircle2, AlertCircle, Loader2, Sparkles, Bot, Database, Globe, Cpu, ArrowRight } from 'lucide-react';
import { cn } from '../utils/cn';

export type NodeStatus = 'idle' | 'running' | 'completed' | 'error';

export interface FlowNode {
  id: string;
  label: string;
  type: string;
  icon?: 'bot' | 'db' | 'globe' | 'cpu';
  status: NodeStatus;
  x: number;
  y: number;
  dataSummary?: string;
}

export interface FlowEdge {
  id: string;
  from: string;
  to: string;
  animated?: boolean;
}

export interface NodeFlowGraphProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Array of initial graph nodes */
  initialNodes?: FlowNode[];
  /** Array of directed edges linking nodes */
  initialEdges?: FlowEdge[];
  /** Whether nodes can be dragged */
  interactive?: boolean;
  /** Whether the execution toolbar is visible */
  showToolbar?: boolean;
  /** Title header for the workflow canvas */
  title?: string;
  /** Theme mode override */
  theme?: 'dark' | 'light' | 'auto';
}

const defaultNodes: FlowNode[] = [
  {
    id: 'n1',
    label: 'AI Intent Classifier',
    type: 'Model Agent',
    icon: 'bot',
    status: 'completed',
    x: 40,
    y: 90,
    dataSummary: 'gpt-4o-mini ~ 99.4% conf',
  },
  {
    id: 'n2',
    label: 'Vector DB Retrieval',
    type: 'Semantic Index',
    icon: 'db',
    status: 'idle',
    x: 290,
    y: 50,
    dataSummary: 'Pinecone / 1536 dims',
  },
  {
    id: 'n3',
    label: 'External API Webhook',
    type: 'Integration',
    icon: 'globe',
    status: 'idle',
    x: 290,
    y: 190,
    dataSummary: 'Stripe v2 Webhook',
  },
  {
    id: 'n4',
    label: 'Synthesis & Dispatch',
    type: 'Executor',
    icon: 'cpu',
    status: 'idle',
    x: 540,
    y: 120,
    dataSummary: '200 OK / 142ms latency',
  },
];

const defaultEdges: FlowEdge[] = [
  { id: 'e1-2', from: 'n1', to: 'n2', animated: true },
  { id: 'e1-3', from: 'n1', to: 'n3', animated: true },
  { id: 'e2-4', from: 'n2', to: 'n4', animated: true },
  { id: 'e3-4', from: 'n3', to: 'n4', animated: true },
];

export const NodeFlowGraph = React.forwardRef<HTMLDivElement, NodeFlowGraphProps>(
  (
    {
      initialNodes = defaultNodes,
      initialEdges = defaultEdges,
      interactive = true,
      showToolbar = true,
      title = 'AGENTIC WORKFLOW PIPELINE',
      theme = 'auto',
      className,
      ...props
    },
    ref
  ) => {
    const [nodes, setNodes] = React.useState<FlowNode[]>(initialNodes);
    const [edges] = React.useState<FlowEdge[]>(initialEdges);
    const [isRunning, setIsRunning] = React.useState(false);
    const [activeEdge, setActiveEdge] = React.useState<string | null>(null);

    const canvasRef = React.useRef<HTMLDivElement>(null);
    const draggingNodeRef = React.useRef<{ id: string; startX: number; startY: number; nodeX: number; nodeY: number } | null>(null);

    // Node dragging handlers
    const handlePointerDown = (id: string, e: React.PointerEvent) => {
      if (!interactive) return;
      const targetNode = nodes.find((n) => n.id === id);
      if (!targetNode) return;

      draggingNodeRef.current = {
        id,
        startX: e.clientX,
        startY: e.clientY,
        nodeX: targetNode.x,
        nodeY: targetNode.y,
      };
      (e.target as Element).setPointerCapture?.(e.pointerId);
    };

    const handlePointerMove = (e: React.PointerEvent) => {
      if (!draggingNodeRef.current) return;
      const { id, startX, startY, nodeX, nodeY } = draggingNodeRef.current;
      const dx = e.clientX - startX;
      const dy = e.clientY - startY;

      setNodes((prev) =>
        prev.map((node) => {
          if (node.id !== id) return node;
          return {
            ...node,
            x: Math.max(10, Math.min(640, nodeX + dx)),
            y: Math.max(10, Math.min(260, nodeY + dy)),
          };
        })
      );
    };

    const handlePointerUp = (e: React.PointerEvent) => {
      if (!draggingNodeRef.current) return;
      (e.target as Element).releasePointerCapture?.(e.pointerId);
      draggingNodeRef.current = null;
    };

    // Sequential pipeline run simulation
    const runPipeline = React.useCallback(async () => {
      if (isRunning) return;
      setIsRunning(true);

      // Reset all nodes
      setNodes((prev) => prev.map((n) => ({ ...n, status: 'idle' })));
      setActiveEdge(null);

      // Step 1: n1 running
      setNodes((prev) => prev.map((n) => (n.id === 'n1' ? { ...n, status: 'running' } : n)));
      await new Promise((r) => setTimeout(r, 700));
      setNodes((prev) => prev.map((n) => (n.id === 'n1' ? { ...n, status: 'completed' } : n)));

      // Data emits along e1-2 & e1-3
      setActiveEdge('e1-2');
      await new Promise((r) => setTimeout(r, 600));

      // Step 2: n2 & n3 running
      setNodes((prev) =>
        prev.map((n) => (n.id === 'n2' || n.id === 'n3' ? { ...n, status: 'running' } : n))
      );
      await new Promise((r) => setTimeout(r, 800));
      setNodes((prev) =>
        prev.map((n) => (n.id === 'n2' || n.id === 'n3' ? { ...n, status: 'completed' } : n))
      );

      // Data emits along e2-4 & e3-4
      setActiveEdge('e2-4');
      await new Promise((r) => setTimeout(r, 600));

      // Step 3: n4 running
      setNodes((prev) => prev.map((n) => (n.id === 'n4' ? { ...n, status: 'running' } : n)));
      await new Promise((r) => setTimeout(r, 750));
      setNodes((prev) => prev.map((n) => (n.id === 'n4' ? { ...n, status: 'completed' } : n)));

      setActiveEdge(null);
      setIsRunning(false);
    }, [isRunning]);

    const resetPipeline = () => {
      setIsRunning(false);
      setActiveEdge(null);
      setNodes(defaultNodes);
    };

    const getNodeCoordinates = (id: string): { outputX: number; outputY: number; inputX: number; inputY: number } => {
      const node = nodes.find((n) => n.id === id);
      if (!node) return { outputX: 0, outputY: 0, inputX: 0, inputY: 0 };
      return {
        outputX: node.x + 190,
        outputY: node.y + 36,
        inputX: node.x,
        inputY: node.y + 36,
      };
    };

    const renderIcon = (icon?: string) => {
      switch (icon) {
        case 'bot':
          return <Bot className="w-3.5 h-3.5 text-cyan-500" />;
        case 'db':
          return <Database className="w-3.5 h-3.5 text-purple-500" />;
        case 'globe':
          return <Globe className="w-3.5 h-3.5 text-emerald-500" />;
        default:
          return <Cpu className="w-3.5 h-3.5 text-amber-500" />;
      }
    };

    return (
      <div
        ref={ref}
        className={cn(
          'relative flex flex-col p-6 rounded-3xl transition-all duration-300 select-none overflow-hidden',
          'bg-white dark:bg-[#07090f] border border-slate-200/90 dark:border-white/10 shadow-2xl shadow-slate-200/50 dark:shadow-black/70 w-full',
          className
        )}
        {...props}
      >
        {/* Top Header */}
        <div className="w-full flex items-center justify-between mb-4 z-10">
          <div className="flex items-center gap-2">
            <Sparkles className="w-4 h-4 text-cyan-500 animate-pulse" />
            <span className="text-xs font-mono font-bold tracking-wider text-slate-800 dark:text-slate-200 uppercase">
              {title}
            </span>
          </div>

          {showToolbar && (
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={resetPipeline}
                disabled={isRunning}
                className="p-1.5 rounded-xl border border-slate-200 dark:border-white/10 bg-slate-100 dark:bg-white/5 text-slate-600 dark:text-slate-300 hover:text-slate-900 dark:hover:text-white transition-colors cursor-pointer disabled:opacity-50"
                title="Reset Workflow"
              >
                <RotateCcw className="w-3.5 h-3.5" />
              </button>

              <button
                type="button"
                onClick={runPipeline}
                disabled={isRunning}
                className={cn(
                  'flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-mono font-bold border transition-all cursor-pointer',
                  isRunning
                    ? 'bg-cyan-500/15 text-cyan-500 border-cyan-500/30'
                    : 'bg-primary text-primary-foreground border-primary hover:opacity-90 shadow-md shadow-primary/20'
                )}
              >
                {isRunning ? (
                  <>
                    <Loader2 className="w-3.5 h-3.5 animate-spin" /> EXECUTING...
                  </>
                ) : (
                  <>
                    <Play className="w-3.5 h-3.5" /> RUN PIPELINE
                  </>
                )}
              </button>
            </div>
          )}
        </div>

        {/* Interactive Graph Canvas */}
        <div
          ref={canvasRef}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          className="relative w-full h-[360px] rounded-2xl bg-slate-50 dark:bg-[#090c14] border border-slate-200/70 dark:border-white/5 overflow-hidden"
          style={{
            backgroundImage:
              'radial-gradient(circle, rgba(148, 163, 184, 0.25) 1px, transparent 1px)',
            backgroundSize: '20px 20px',
          }}
        >
          {/* Connecting SVG Bezier Spline Cables */}
          <svg className="absolute inset-0 w-full h-full pointer-events-none z-0">
            <defs>
              <linearGradient id="flow-cable-grad" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor="#06b6d4" />
                <stop offset="50%" stopColor="#8b5cf6" />
                <stop offset="100%" stopColor="#10b981" />
              </linearGradient>
              <filter id="cable-glow">
                <feGaussianBlur stdDeviation="3" result="blur" />
                <feMerge>
                  <feMergeNode in="blur" />
                  <feMergeNode in="SourceGraphic" />
                </feMerge>
              </filter>
            </defs>

            {edges.map((edge) => {
              const fromCoords = getNodeCoordinates(edge.from);
              const toCoords = getNodeCoordinates(edge.to);

              const x1 = fromCoords.outputX;
              const y1 = fromCoords.outputY;
              const x2 = toCoords.inputX;
              const y2 = toCoords.inputY;

              const dx = Math.abs(x2 - x1) * 0.55;
              const pathD = \`M \${x1} \${y1} C \${x1 + dx} \${y1}, \${x2 - dx} \${y2}, \${x2} \${y2}\`;

              const isEdgeActive = isRunning || activeEdge === edge.id;

              return (
                <g key={edge.id}>
                  {/* Background Cable Wire */}
                  <path
                    d={pathD}
                    fill="none"
                    stroke="currentColor"
                    strokeWidth={2}
                    className="text-slate-300 dark:text-slate-800"
                  />
                  {/* Active Highlight Cable */}
                  {isEdgeActive && (
                    <path
                      d={pathD}
                      fill="none"
                      stroke="url(#flow-cable-grad)"
                      strokeWidth={2.5}
                      filter="url(#cable-glow)"
                      strokeDasharray="6 4"
                      className="animate-pulse"
                    />
                  )}
                </g>
              );
            })}
          </svg>

          {/* Render Flow Nodes */}
          {nodes.map((node) => (
            <div
              key={node.id}
              onPointerDown={(e) => handlePointerDown(node.id, e)}
              style={{
                transform: \`translate3d(\${node.x}px, \${node.y}px, 0)\`,
              }}
              className={cn(
                'absolute w-[190px] rounded-xl p-3 select-none transition-shadow duration-200 z-10',
                interactive ? 'cursor-grab active:cursor-grabbing' : 'cursor-default',
                'bg-white dark:bg-[#0e121c] border border-slate-200/90 dark:border-white/10 shadow-lg',
                node.status === 'running' && 'ring-2 ring-cyan-400 shadow-[0_0_20px_rgba(6,182,212,0.3)]',
                node.status === 'completed' && 'border-emerald-500/40'
              )}
            >
              {/* Input Port Anchor */}
              <div className="absolute -left-1.5 top-1/2 -translate-y-1/2 w-3 h-3 rounded-full bg-slate-100 dark:bg-zinc-800 border-2 border-primary" />

              {/* Output Port Anchor */}
              <div className="absolute -right-1.5 top-1/2 -translate-y-1/2 w-3 h-3 rounded-full bg-slate-100 dark:bg-zinc-800 border-2 border-emerald-500" />

              {/* Node Header Row */}
              <div className="flex items-center justify-between gap-1.5 mb-1.5">
                <div className="flex items-center gap-1.5">
                  <div className="p-1 rounded-md bg-slate-100 dark:bg-white/5 border border-slate-200 dark:border-white/10">
                    {renderIcon(node.icon)}
                  </div>
                  <span className="text-[10px] font-mono text-slate-400 uppercase">{node.type}</span>
                </div>

                {/* Status Indicator */}
                {node.status === 'running' ? (
                  <Loader2 className="w-3.5 h-3.5 text-cyan-400 animate-spin" />
                ) : node.status === 'completed' ? (
                  <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" />
                ) : node.status === 'error' ? (
                  <AlertCircle className="w-3.5 h-3.5 text-rose-500" />
                ) : (
                  <div className="w-2 h-2 rounded-full bg-slate-300 dark:bg-slate-700" />
                )}
              </div>

              {/* Node Title */}
              <h4 className="text-xs font-bold text-slate-800 dark:text-slate-100 leading-tight">
                {node.label}
              </h4>

              {/* Data Summary Subtext */}
              {node.dataSummary && (
                <div className="mt-2 pt-1.5 border-t border-slate-100 dark:border-white/5 text-[10px] font-mono text-slate-500 dark:text-slate-400 truncate">
                  {node.dataSummary}
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    );
  }
);

NodeFlowGraph.displayName = 'NodeFlowGraph';

number-ticker.content:
"use client"

import * as React from "react"
import { motion, useMotionValue, useSpring, useTransform, useInView } from "framer-motion"
import { cn } from "../utils/cn"

/**
 * Props for the NumberTicker component
 */
export interface NumberTickerProps extends React.HTMLAttributes<HTMLSpanElement> {
  /**
   * The target numeric value to animate to
   */
  value: number
  /**
   * Duration of the animation in seconds
   * @default 2
   */
  duration?: number
  /**
   * Optional prefix to display before the number
   */
  prefix?: string
  /**
   * Optional suffix to display after the number
   */
  suffix?: string
  /**
   * Number of decimal places to show
   * @default 0
   */
  decimals?: number
  /**
   * Additional CSS classes
   */
  className?: string
}

/**
 * NumberTicker component animates a number from 0 to value when it enters the viewport.
 */
const NumberTicker = React.forwardRef<HTMLSpanElement, NumberTickerProps>(
  (
    {
      value,
      duration = 2,
      prefix = "",
      suffix = "",
      decimals = 0,
      className,
      ...props
    },
    ref
  ) => {
    const elementRef = React.useRef<HTMLSpanElement>(null)
    const combinedRef = (ref as React.RefObject<HTMLSpanElement>) || elementRef
    const inView = useInView(combinedRef, { once: true, margin: "0px 0px -50px 0px" })

    // Motion value initialized to 0
    const motionValue = useMotionValue(0)

    // Spring animation for natural spring physics feel
    const springValue = useSpring(motionValue, {
      stiffness: 70,
      damping: 15,
      mass: 1,
    })

    // Transform spring output to clean formatted string
    const displayValue = useTransform(springValue, (latest) => {
      const formatted = Number(latest.toFixed(decimals))
      return formatted.toLocaleString("en-US", {
        minimumFractionDigits: decimals,
        maximumFractionDigits: decimals,
      })
    })

    React.useEffect(() => {
      if (inView) {
        // Animate the motion value from 0 to the target value
        motionValue.set(value)
      }
    }, [inView, value, motionValue])

    return (
      <span
        ref={combinedRef}
        className={cn(
          "inline-block tabular-nums text-foreground tracking-tight",
          className
        )}
        {...props}
      >
        {prefix}
        <motion.span>{displayValue}</motion.span>
        {suffix}
      </span>
    )
  }
)

NumberTicker.displayName = "NumberTicker"

export { NumberTicker }

export interface AnimatedNumberProps {
  value: number
  className?: string
  duration?: number
  formatFn?: (v: number) => string
}

export function AnimatedNumber({
  value,
  className,
  duration: _duration = 0.5,
  formatFn,
}: AnimatedNumberProps) {
  const motionValue = useMotionValue(value)
  const springValue = useSpring(motionValue, {
    stiffness: 100,
    damping: 15,
  })

  React.useEffect(() => {
    motionValue.set(value)
  }, [value, motionValue])

  const [displayValue, setDisplayValue] = React.useState(
    formatFn ? formatFn(value) : String(value)
  )

  React.useEffect(() => {
    const unsubscribe = springValue.on("change", (latest) => {
      if (formatFn) {
        setDisplayValue(formatFn(latest))
      } else {
        setDisplayValue(String(Math.round(latest)))
      }
    })
    return () => unsubscribe()
  }, [springValue, formatFn])

  return (
    <span className={cn("inline-block tabular-nums", className)}>
      {displayValue}
    </span>
  )
}

particle-reveal-card.content:
"use client";

import * as React from "react";
import { useState, useRef, useEffect, useCallback, useId } from "react";
import { cn } from "../utils/cn";
import { Sparkles, RotateCcw } from "lucide-react";

export interface ParticleRevealCardProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Transparent PNG image URL of the product or object.
   */
  src: string;
  /**
   * Card title or product name.
   */
  title?: string;
  /**
   * Secondary label or subtitle.
   */
  subtitle?: string;
  /**
   * Optional price string.
   */
  price?: string;
  /**
   * Badge text displayed at top of card.
   */
  badge?: string;
  /**
   * Card width in pixels or CSS dimension string.
   * @default 360
   */
  cardWidth?: number | string;
  /**
   * Card height in pixels or CSS dimension string.
   * @default 480
   */
  cardHeight?: number | string;
  /**
   * Diameter of each pixel particle in pixels.
   * @default 2.2
   */
  particleSize?: number;
  /**
   * Sampling step/gap between sampled pixels. Lower value = higher particle density.
   * @default 3
   */
  gap?: number;
  /**
   * Cursor repulsion radius in pixels.
   * @default 85
   */
  repelRadius?: number;
  /**
   * Repulsion force multiplier.
   * @default 6.5
   */
  repelForce?: number;
  /**
   * Spring stiffness pulling particles back to their home coordinate.
   * @default 0.08
   */
  springStiffness?: number;
  /**
   * Velocity friction/damping factor (0.8 - 0.95).
   * @default 0.88
   */
  damping?: number;
  /**
   * Whether particles scatter randomly on initial load and spring-assemble.
   * @default true
   */
  scatterOnLoad?: boolean;
}

interface Particle {
  homeX: number;
  homeY: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  color: string;
}

/**
 * ParticleRevealCard
 *
 * Luxury showcase card where the product photo assembles from thousands of floating
 * particles upon load with spring physics, and the cursor dynamically repels particles.
 */
export const ParticleRevealCard = React.forwardRef<HTMLDivElement, ParticleRevealCardProps>(
  (
    {
      src,
      title = "Quantum Chronograph",
      subtitle = "CALIBRE 01 • FORGED TITANIUM",
      price = "$1,450",
      badge = "Particle Physics",
      cardWidth = 360,
      cardHeight = 480,
      particleSize = 2.2,
      gap = 3,
      repelRadius = 85,
      repelForce = 6.5,
      springStiffness = 0.08,
      damping = 0.88,
      scatterOnLoad = true,
      className,
      style,
      ...props
    },
    ref
  ) => {
    const cardId = useId();
    const containerRef = useRef<HTMLDivElement>(null);
    const canvasRef = useRef<HTMLCanvasElement | null>(null);
    const particlesRef = useRef<Particle[]>([]);
    const animFrameRef = useRef<number | null>(null);
    const pointerRef = useRef<{ x: number; y: number; active: boolean }>({
      x: -9999,
      y: -9999,
      active: false,
    });

    const [isLoaded, setIsLoaded] = useState(false);
    const [particleCount, setParticleCount] = useState(0);

    // Scatter particles to random explosive offsets
    const triggerScatter = useCallback(() => {
      const particles = particlesRef.current;
      const canvas = canvasRef.current;
      if (!canvas || particles.length === 0) return;

      const cw = canvas.width;
      const ch = canvas.height;

      for (let i = 0; i < particles.length; i++) {
        const p = particles[i];
        const angle = Math.random() * Math.PI * 2;
        const dist = 100 + Math.random() * Math.max(cw, ch) * 0.8;
        p.vx = Math.cos(angle) * (6 + Math.random() * 8);
        p.vy = Math.sin(angle) * (6 + Math.random() * 8);
        p.x = p.homeX + Math.cos(angle) * dist;
        p.y = p.homeY + Math.sin(angle) * dist;
      }
    }, []);

    // Load and sample transparent PNG pixels
    useEffect(() => {
      if (!src) return;
      let cancelled = false;
      setIsLoaded(false);

      const img = new Image();
      img.crossOrigin = "anonymous";
      img.src = src;

      img.onload = () => {
        if (cancelled) return;

        const canvas = canvasRef.current;
        if (!canvas) return;

        const dpr = typeof window !== "undefined" ? Math.min(window.devicePixelRatio || 1, 2) : 1;
        const displayWidth = canvas.clientWidth || 320;
        const displayHeight = canvas.clientHeight || 280;

        canvas.width = displayWidth * dpr;
        canvas.height = displayHeight * dpr;

        const offscreen = document.createElement("canvas");
        const offCtx = offscreen.getContext("2d", { willReadFrequently: true });
        if (!offCtx) return;

        // Scale image to fit comfortably within display bounds with margins
        const padding = 20;
        const maxW = displayWidth - padding * 2;
        const maxH = displayHeight - padding * 2;
        const scale = Math.min(maxW / img.width, maxH / img.height);
        const drawW = img.width * scale;
        const drawH = img.height * scale;
        const offsetX = (displayWidth - drawW) / 2;
        const offsetY = (displayHeight - drawH) / 2;

        offscreen.width = displayWidth;
        offscreen.height = displayHeight;

        offCtx.clearRect(0, 0, displayWidth, displayHeight);
        offCtx.drawImage(img, offsetX, offsetY, drawW, drawH);

        const imgData = offCtx.getImageData(0, 0, displayWidth, displayHeight);
        const pixels = imgData.data;
        const newParticles: Particle[] = [];

        const samplingGap = Math.max(2, Math.round(gap));

        for (let y = 0; y < displayHeight; y += samplingGap) {
          for (let x = 0; x < displayWidth; x += samplingGap) {
            const index = (y * displayWidth + x) * 4;
            const alpha = pixels[index + 3];

            // Only sample solid silhouette pixels
            if (alpha > 30) {
              const r = pixels[index];
              const g = pixels[index + 1];
              const b = pixels[index + 2];
              const a = (alpha / 255).toFixed(2);

              const homeX = x * dpr;
              const homeY = y * dpr;

              let startX = homeX;
              let startY = homeY;
              let startVx = 0;
              let startVy = 0;

              if (scatterOnLoad) {
                const angle = Math.random() * Math.PI * 2;
                const dist = 120 + Math.random() * Math.max(displayWidth, displayHeight) * 0.9 * dpr;
                startX = homeX + Math.cos(angle) * dist;
                startY = homeY + Math.sin(angle) * dist;
                startVx = (Math.random() - 0.5) * 8;
                startVy = (Math.random() - 0.5) * 8;
              }

              newParticles.push({
                homeX,
                homeY,
                x: startX,
                y: startY,
                vx: startVx,
                vy: startVy,
                color: `rgba(${r},${g},${b},${a})`,
              });
            }
          }
        }

        particlesRef.current = newParticles;
        setParticleCount(newParticles.length);
        setIsLoaded(true);
      };

      return () => {
        cancelled = true;
      };
    }, [src, gap, scatterOnLoad]);

    // Canvas Physics Animation Loop
    useEffect(() => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;

      let isRunning = true;

      const render = () => {
        if (!isRunning) return;

        const dpr = typeof window !== "undefined" ? Math.min(window.devicePixelRatio || 1, 2) : 1;
        const particles = particlesRef.current;
        const ptr = pointerRef.current;

        ctx.clearRect(0, 0, canvas.width, canvas.height);

        const scaledRepelRad = repelRadius * dpr;
        const scaledRepelRadSq = scaledRepelRad * scaledRepelRad;
        const pSize = particleSize * dpr;

        for (let i = 0; i < particles.length; i++) {
          const p = particles[i];

          // 1. Cursor Repulsion
          if (ptr.active) {
            const dx = p.x - ptr.x;
            const dy = p.y - ptr.y;
            const distSq = dx * dx + dy * dy;

            if (distSq < scaledRepelRadSq && distSq > 0) {
              const dist = Math.sqrt(distSq);
              const force = (1 - dist / scaledRepelRad) * repelForce * dpr;
              const angle = Math.atan2(dy, dx);
              p.vx += Math.cos(angle) * force;
              p.vy += Math.sin(angle) * force;
            }
          }

          // 2. Spring Physics to Home
          const homeDx = p.homeX - p.x;
          const homeDy = p.homeY - p.y;
          p.vx += homeDx * springStiffness;
          p.vy += homeDy * springStiffness;

          // 3. Friction & Position Integration
          p.vx *= damping;
          p.vy *= damping;
          p.x += p.vx;
          p.y += p.vy;

          // 4. Render Particle
          ctx.fillStyle = p.color;
          ctx.fillRect(p.x - pSize / 2, p.y - pSize / 2, pSize, pSize);
        }

        animFrameRef.current = requestAnimationFrame(render);
      };

      animFrameRef.current = requestAnimationFrame(render);

      return () => {
        isRunning = false;
        if (animFrameRef.current) {
          cancelAnimationFrame(animFrameRef.current);
        }
      };
    }, [particleSize, repelRadius, repelForce, springStiffness, damping]);

    // Pointer Event Handlers
    const handlePointerMove = useCallback((e: React.PointerEvent<HTMLDivElement>) => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const rect = canvas.getBoundingClientRect();
      const dpr = typeof window !== "undefined" ? Math.min(window.devicePixelRatio || 1, 2) : 1;

      const px = (e.clientX - rect.left) * dpr;
      const py = (e.clientY - rect.top) * dpr;

      pointerRef.current = {
        x: px,
        y: py,
        active: true,
      };
    }, []);

    const handlePointerLeave = useCallback(() => {
      pointerRef.current.active = false;
    }, []);

    return (
      <div
        ref={ref}
        className={cn("group flex flex-col items-center select-none", className)}
        style={{
          width: typeof cardWidth === "number" ? `${cardWidth}px` : cardWidth,
          ...style,
        }}
        {...props}
      >
        <div
          ref={containerRef}
          onPointerMove={handlePointerMove}
          onPointerLeave={handlePointerLeave}
          className="relative w-full rounded-2xl p-5 border border-white/10 bg-[hsl(225_12%_7%)] hover:border-white/20 transition-all duration-300 shadow-2xl overflow-hidden flex flex-col justify-between"
          style={{
            minHeight: typeof cardHeight === "number" ? `${cardHeight}px` : cardHeight,
          }}
        >
          {/* Subtle Aurora Ambient Radial Glow */}
          <div className="absolute -top-24 left-1/2 -translate-x-1/2 w-64 h-64 bg-cyan-500/10 rounded-full blur-3xl pointer-events-none" />
          <div className="absolute -bottom-24 right-0 w-64 h-64 bg-indigo-500/10 rounded-full blur-3xl pointer-events-none" />

          {/* Top Header Plate */}
          <div className="relative z-10 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <span className="w-1.5 h-1.5 rounded-full bg-cyan-400 animate-pulse" />
              <span className="text-[11px] font-mono font-semibold uppercase tracking-wider text-cyan-400/90">
                {badge}
              </span>
            </div>

            {/* Scatter Re-trigger Button */}
            <button
              type="button"
              onClick={triggerScatter}
              className="flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-[10px] font-mono text-zinc-400 hover:text-white bg-white/5 hover:bg-white/10 border border-white/8 transition-all cursor-pointer active:scale-95"
              title="Re-scatter particles"
            >
              <RotateCcw className="w-3 h-3" />
              <span>Scatter</span>
            </button>
          </div>

          {/* Center Stage: Interactive Particle Canvas */}
          <div className="relative w-full h-[260px] my-auto flex items-center justify-center">
            <canvas
              ref={canvasRef}
              className="w-full h-full cursor-crosshair touch-none"
            />

            {!isLoaded && (
              <div className="absolute inset-0 flex flex-col items-center justify-center gap-2 text-zinc-500">
                <Sparkles className="w-5 h-5 animate-spin text-cyan-400" />
                <span className="text-xs font-mono">Synthesizing particles...</span>
              </div>
            )}
          </div>

          {/* Bottom Card Typographic Plate */}
          <div className="relative z-10 border-t border-white/8 pt-4">
            <div className="flex items-baseline justify-between mb-1">
              <h3 className="text-base font-semibold text-white tracking-tight">
                {title}
              </h3>
              {price && (
                <span className="text-sm font-mono font-bold text-cyan-400">
                  {price}
                </span>
              )}
            </div>

            <div className="flex items-center justify-between">
              <p className="text-xs text-zinc-400 font-mono tracking-wide">
                {subtitle}
              </p>
              {particleCount > 0 && (
                <span className="text-[10px] font-mono text-zinc-500">
                  {particleCount.toLocaleString()} pts
                </span>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  }
);

