/* ━━━ Base Styles ━━━ */
@layer base {
  * {
    border-color: var(--color-border);
  }

  body {
    background-color: var(--color-background);
    color: var(--color-foreground);
    font-family: var(--font-sans, "Geist"), system-ui, -apple-system, sans-serif;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  /* Thin, unobtrusive scrollbars */
  ::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background: hsl(0 0% 98% / 0.1);
    border-radius: 9999px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: hsl(0 0% 98% / 0.2);
  }

  ::selection {
    background: hsl(0 0% 98% / 0.12);
  }
}

/* ━━━ Component Patterns ━━━ */
.demo-grid-pattern {
  background-color: var(--color-background);
  background-image: 
    linear-gradient(to right, rgba(0, 0, 0, 0.055) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(0, 0, 0, 0.055) 1px, transparent 1px);
  background-size: 24px 24px;
}

.dark .demo-grid-pattern {
  background-color: hsl(240 10% 4%);
  background-image: 
    linear-gradient(to right, rgba(255, 255, 255, 0.045) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(255, 255, 255, 0.045) 1px, transparent 1px);
}

.code-block {
