  100% { transform: rotate(360deg); }
}
@keyframes spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}
@property --aurora-deg {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
