    --aurora-deg: 0deg;
  }
  100% {
    --aurora-deg: 360deg;
  }
}

/* ━━━ Animation Utilities ━━━ */
@utility animate-marquee-left {
  animation: marquee-left var(--duration) linear infinite;
}
@utility animate-marquee-right {
  animation: marquee-right var(--duration) linear infinite;
}
