/* ═══ Monochrome Scrollbars — appear on hover ═══ */
.scrollbar-thin {
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
  transition: scrollbar-color 0.3s ease;
}
.scrollbar-thin:hover {
  scrollbar-color: rgba(255, 255, 255, 0.2) transparent;
}
.scrollbar-thin::-webkit-scrollbar {
  width: 4px;
  height: 4px;
}
.scrollbar-thin::-webkit-scrollbar-track {
  background: transparent;
}
.scrollbar-thin::-webkit-scrollbar-thumb {
  background: transparent;
  border-radius: 9999px;
  transition: background 0.3s ease;
}
.scrollbar-thin:hover::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.2);
}
.scrollbar-thin::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.4);
}

/* Properties and toolbar scrollbar */
.properties-scroll-container,
.toolbar-scroll-container {
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
}
.properties-scroll-container:hover,
.toolbar-scroll-container:hover {
  scrollbar-color: rgba(255, 255, 255, 0.2) transparent;
}
.properties-scroll-container::-webkit-scrollbar,
.toolbar-scroll-container::-webkit-scrollbar {
  width: 4px;
}
.properties-scroll-container::-webkit-scrollbar-track,
.toolbar-scroll-container::-webkit-scrollbar-track {
  background: transparent;
}
.properties-scroll-container::-webkit-scrollbar-thumb,
.toolbar-scroll-container::-webkit-scrollbar-thumb {
  background: transparent;
  border-radius: 9999px;
}
.properties-scroll-container:hover::-webkit-scrollbar-thumb,
