  background: rgba(255, 255, 255, 0.2);
}
.properties-scroll-container::-webkit-scrollbar-thumb:hover,
.toolbar-scroll-container::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.4);
}

/* Hide scrollbar for generic containers */
.hide-scrollbar::-webkit-scrollbar {
  display: none;
}
.hide-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

/* ═══ Nexore Make Animations ═══ */
@keyframes make-glow-pulse {
  0%, 100% { box-shadow: 0 0 4px rgba(139, 92, 246, 0.3), 0 0 8px rgba(139, 92, 246, 0.1); }
