  --nx-glow-shadow: rgba(255, 255, 255, 0.2);
  -webkit-mask-image: linear-gradient(#000 52%, transparent 96%);
  mask-image: linear-gradient(#000 52%, transparent 96%);
}

.nx-row {
  display: flex;
  justify-content: center;
  white-space: nowrap;
}

.nx-l {
  display: inline-block;
  color: var(--nx-fill);
  opacity: 0;
  transform: translateY(110%);
  -webkit-text-stroke: var(--nx-stroke-width) var(--nx-stroke);
}

.in .nx-l {
  animation:
    nx-rise 0.9s cubic-bezier(0.16, 1, 0.3, 1) calc(var(--i) * 60ms) forwards,
    nx-wave 4s ease-in-out calc(var(--i) * 0.25s + 1.2s) infinite;
}

/* Слой подсветки под курсором в стиле темы сайта */
.nx-glow {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: var(--o);
  transition: opacity 0.35s ease-out;
  -webkit-mask-image: radial-gradient(circle 280px at var(--x) var(--y), #000, transparent 70%);
  mask-image: radial-gradient(circle 280px at var(--x) var(--y), #000, transparent 70%);
  filter: drop-shadow(0 0 24px var(--nx-glow-shadow));
}

.nx-glow .nx-l {
  -webkit-text-stroke: 1px var(--nx-glow-stroke);
  background: var(--nx-glow-gradient);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

@keyframes nx-rise {
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes nx-wave {
  0%, 100% {
    -webkit-text-stroke-color: var(--nx-stroke);
    color: var(--nx-fill);
  }
  50% {
    -webkit-text-stroke-color: var(--nx-stroke-wave);
    color: var(--nx-wave-fill);
  }
}

@media (prefers-reduced-motion: reduce) {
  .in .nx-l {
    animation: nx-rise 0.01s forwards;
  }
  .nx-glow {
    transition: none;
  }
}
